:root {
  --bg: #0f1720;
  --bg2: #16212e;
  --panel: #1b2735;
  --panel2: #223247;
  --line: #2c3e52;
  --text: #e8eef5;
  --muted: #9fb0c3;
  --accent: #4aa3ff;
  --you: #f4f6f8;      /* white checkers */
  --you-edge: #b9c2cc;
  --ai: #21262d;       /* black/dark checkers */
  --ai-edge: #4a5568;
  --felt: #14563a;     /* board felt */
  --felt2: #0f4530;
  --wood: #6b4423;
  --wood2: #4e3117;
  --tri-a: #c98a4b;    /* light triangle */
  --tri-b: #7c4a24;    /* dark triangle */
  --hint: #ffd24a;

display.text:
:root {
  --bg: #0f1720;
  --bg2: #16212e;
  --panel: #1b2735;
  --panel2: #223247;
  --line: #2c3e52;
  --text: #e8eef5;
  --muted: #9fb0c3;
  --accent: #4aa3ff;
  --you: #f4f6f8;      /* white checkers */
  --you-edge: #b9c2cc;
  --ai: #21262d;       /* black/dark checkers */
  --ai-edge: #4a5568;
  --felt: #14563a;     /* board felt */
  --felt2: #0f4530;
  --wood: #6b4423;
  --wood2: #4e3117;
  --tri-a: #c98a4b;    /* light triangle */
  --tri-b: #7c4a24;    /* dark triangle */
  --hint: #ffd24a;
  --good: #57d38c;
  --bad: #ff6b6b;
  --checker: min(4.2vh, 3.0vw);
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: "Segoe UI", system-ui, -apple-system, Roboto, Helvetica, Arial, sans-serif;
  background: radial-gradient(1200px 700px at 50% -10%, #1c2a3a, var(--bg));
  color: var(--text);
  height: 100vh;
  overflow: hidden;
}
#app { height: 100vh; display: flex; flex-direction: column; padding: 10px 14px; gap: 10px; }

/* ---------- top bar ---------- */
#topbar {
  display: grid; grid-template-columns: 1fr auto 1fr; align-items: center;
  padding: 4px 6px;
}
.brand { display: flex; align-items: center; gap: 10px; }
.brand .logo { font-size: 26px; color: var(--accent); }
.brand h1 { font-size: 20px; letter-spacing: .5px; font-weight: 700; }
.topcenter { display: flex; justify-content: center; }
.score { display: flex; gap: 8px; }
.pill { background: var(--panel); border: 1px solid var(--line); padding: 4px 12px; border-radius: 20px; font-size: 13px; color: var(--muted); }
.pill b { color: var(--text); font-size: 15px; margin-left: 4px; }
.pill.you b { color: #fff; }
.pill.ai b { color: #ffd27a; }
.controls { display: flex; gap: 8px; justify-content: flex-end; align-items: center; }
.difwrap { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; }
select, .btn {
  background: var(--panel2); color: var(--text); border: 1px solid var(--line);
  border-radius: 8px; padding: 7px 12px; font-size: 13px; cursor: pointer;
  transition: background .15s, transform .05s, opacity .15s;
}
select:hover, .btn:hover { background: #2c4763; }
.btn:active { transform: translateY(1px); }
.btn:disabled { opacity: .4; cursor: not-allowed; }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #05233f; font-weight: 700; }
.btn.primary:hover { background: #6cb6ff; }

/* ---------- table layout ---------- */
#tablewrap { flex: 1; display: flex; gap: 14px; min-height: 0; align-items: stretch; }
#board { flex: 1; min-width: 0; display: flex; align-items: center; justify-content: center; }
.frame {
  position: relative;
  aspect-ratio: 15 / 10;
  height: 100%;
  max-height: 100%;
  max-width: 100%;
  background: linear-gradient(160deg, var(--wood), var(--wood2));
  border-radius: 12px;
  padding: 1.4%;
  box-shadow: 0 18px 50px rgba(0,0,0,.5), inset 0 0 0 3px rgba(0,0,0,.25);
}
.playfield {
  position: absolute; inset: 1.4%;
  display: grid;
  grid-template-columns: repeat(6, 1fr) 6.5% repeat(6, 1fr) 9%;
  grid-template-rows: 1fr 1fr;
  background:
    linear-gradient(var(--felt), var(--felt2));
  border-radius: 6px;
  overflow: hidden;
  box-shadow: inset 0 0 40px rgba(0,0,0,.45);
}
.point {
  position: relative;
}
.point::before {
  content: "";
  position: absolute; left: 8%; right: 8%;
  height: 88%;
}
.point.top::before { top: 0; }
.point.bottom::before { bottom: 0; }
.point.top.a::before { background: linear-gradient(var(--tri-a), color-mix(in srgb, var(--tri-a) 55%, #000)); clip-path: polygon(0 0, 100% 0, 50% 100%); }
.point.top.b::before { background: linear-gradient(var(--tri-b), color-mix(in srgb, var(--tri-b) 55%, #000)); clip-path: polygon(0 0, 100% 0, 50% 100%); }
.point.bottom.a::before { background: linear-gradient(color-mix(in srgb, var(--tri-a) 55%, #000), var(--tri-a)); clip-path: polygon(50% 0, 0 100%, 100% 100%); }
.point.bottom.b::before { background: linear-gradient(color-mix(in srgb, var(--tri-b) 55%, #000), var(--tri-b)); clip-path: polygon(50% 0, 0 100%, 100% 100%); }
.point .plabel {
  position: absolute; left: 0; right: 0; text-align: center; font-size: 9px; color: rgba(255,255,255,.35);
}
.point.top .plabel { top: 1px; }
.point.bottom .plabel { bottom: 1px; }

.bar {
  grid-row: 1 / span 2;
  background: linear-gradient(160deg, var(--wood), var(--wood2));
  box-shadow: inset 0 0 14px rgba(0,0,0,.6);
}
.bar.barcol { grid-column: 7; }
.offtray {
  grid-row: 1 / span 2; grid-column: 14;
  background: linear-gradient(160deg, #2a1a0d, #1a1109);
  box-shadow: inset 0 0 16px rgba(0,0,0,.7);
  position: relative;
  display: flex; flex-direction: column;
}
.offhalf { flex: 1; position: relative; }
.offhalf .offlabel { position: absolute; left: 0; right: 0; text-align: center; font-size: 9px; color: var(--muted); }
.offhalf.top .offlabel { top: 2px; }
.offhalf.bottom .offlabel { bottom: 2px; }

/* ---------- checkers ---------- */
#checkerLayer, #pointHints { position: absolute; inset: 1.4%; pointer-events: none; }
.checker {
  position: absolute;
  width: var(--csize);
  height: var(--csize);
  border-radius: 50%;
  transition: transform .34s cubic-bezier(.34,.9,.4,1);
  will-change: transform;
  box-shadow: 0 2px 4px rgba(0,0,0,.5);
  display: flex; align-items: center; justify-content: center;
}
.checker.white {
  background: radial-gradient(circle at 35% 30%, #ffffff, var(--you) 55%, #cfd6dd 100%);
  border: 2px solid var(--you-edge);
}
.checker.white::after { content:""; width: 42%; height: 42%; border-radius:50%; border: 2px solid rgba(120,130,140,.35); }
.checker.black {
  background: radial-gradient(circle at 35% 30%, #3a4350, var(--ai) 60%, #05070a 100%);
  border: 2px solid var(--ai-edge);
}
.checker.black::after { content:""; width: 42%; height: 42%; border-radius:50%; border: 2px solid rgba(255,255,255,.10); }
.checker.selectable { cursor: pointer; pointer-events: auto; }
.checker.selectable:hover { filter: brightness(1.15); }
.checker.selected { box-shadow: 0 0 0 3px var(--hint), 0 2px 6px rgba(0,0,0,.6); }
.checker .countbadge {
  position: absolute; font-size: 11px; font-weight: 700;
  color: #fff; text-shadow: 0 1px 2px #000; pointer-events: none;
}
.checker.black .countbadge { color: #ffd27a; }

/* landing hints */
.hint {
  position: absolute; border-radius: 50%;
  width: var(--csize); height: var(--csize);
  border: 3px dashed var(--hint);
  background: rgba(255,210,74,.14);
  display: flex; align-items: center; justify-content: center;
  color: var(--hint); font-weight: 800; font-size: 12px;
  cursor: pointer; pointer-events: auto;
  animation: pulse 1.1s ease-in-out infinite;
}
.hint:hover { background: rgba(255,210,74,.32); }
@keyframes pulse { 0%,100%{ transform: scale(1);} 50%{ transform: scale(1.08);} }

/* ---------- side panel ---------- */
#sidepanel { width: 232px; flex-shrink: 0; display: flex; flex-direction: column; gap: 10px; }
.panelcard { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 12px; }
.turnrow { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.turnlabel { color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 1px; }
.turnchip { padding: 4px 12px; border-radius: 16px; font-weight: 700; font-size: 13px; }
.turnchip.you { background: #eaf1f8; color: #12212f; }
.turnchip.ai { background: #2a3444; color: #ffd27a; border: 1px solid var(--ai-edge); }
.pipbox { display: flex; gap: 8px; }
.pip { flex: 1; background: var(--panel2); border-radius: 8px; padding: 6px 8px; text-align: center; }
.pip span { display: block; font-size: 10px; color: var(--muted); }
.pip b { font-size: 18px; }
.pip.you b { color: #fff; } .pip.ai b { color: #ffd27a; }

.dicebox { display: flex; align-items: center; gap: 12px; justify-content: center; min-height: 74px; }
.cube {
  width: 46px; height: 46px; border-radius: 8px;
  background: linear-gradient(145deg, #f3f5f7, #c9d0d7);
  color: #12212f; display: flex; flex-direction: column; align-items: center; justify-content: center;
  border: 2px solid #aab4bd; box-shadow: 0 3px 6px rgba(0,0,0,.4);
}
.cubeval { font-size: 20px; font-weight: 800; line-height: 1; }
.cubeowner { font-size: 8px; text-transform: uppercase; letter-spacing: .5px; color: #45586b; }
.dice { display: flex; gap: 10px; }
.die {
  width: 40px; height: 40px; border-radius: 9px;
  background: linear-gradient(145deg, #fdfdfd, #e2e6ea);
  position: relative; box-shadow: 0 3px 6px rgba(0,0,0,.45);
  display: grid; grid-template-columns: repeat(3,1fr); grid-template-rows: repeat(3,1fr);
  padding: 5px;
}
.die.used { opacity: .32; }
.die.rolling { animation: shake .5s ease; }
@keyframes shake {
  0%,100%{ transform: translateY(0) rotate(0);}
  20%{ transform: translateY(-6px) rotate(-12deg);}
  40%{ transform: translateY(4px) rotate(10deg);}
  60%{ transform: translateY(-3px) rotate(-6deg);}
  80%{ transform: translateY(2px) rotate(4deg);}
}
.die .dot { width: 7px; height: 7px; background: #1a1f26; border-radius: 50%; align-self: center; justify-self: center; }
.die .dot.hidden { visibility: hidden; }

.actionbox { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.actionbox .btn { width: 100%; }
.msgbox { flex: 1; overflow: auto; }
#message { font-size: 13px; line-height: 1.5; color: var(--muted); }
#message b { color: var(--text); }
#message.good { color: var(--good); }
#message.bad { color: var(--bad); }

/* ---------- modal ---------- */
.overlay {
  position: fixed; inset: 0; background: rgba(4,8,14,.72);
  display: flex; align-items: center; justify-content: center; z-index: 50;
  backdrop-filter: blur(3px);
}
.overlay.hidden { display: none; }
.modal {
  background: var(--panel); border: 1px solid var(--line); border-radius: 16px;
  padding: 26px 28px; max-width: 440px; width: calc(100% - 40px);
  box-shadow: 0 24px 70px rgba(0,0,0,.6); text-align: center;
  animation: pop .22s ease;
}
@keyframes pop { from { transform: scale(.9); opacity: 0; } to { transform: scale(1); opacity: 1; } }
.modal h2 { font-size: 22px; margin-bottom: 12px; }
.modal p { color: var(--muted); line-height: 1.55; margin-bottom: 20px; font-size: 14px; }
.modal p b { color: var(--text); }
.modalbtns { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.modalbtns .btn { padding: 10px 20px; font-size: 14px; }

@media (max-width: 820px) {
  #sidepanel { width: 190px; }
}

