input.content:
// Backgammon core engine — pure logic, no I/O.
//
// Conventions:
//   Points are numbered 1..24.  points[0] and points[25] are reserved sentinels.
//   White (the human) moves from HIGH points to LOW points (24 -> 1). White home = 1..6.
//   Black (the AI) moves from LOW points to HIGH points (1 -> 24).  Black home = 19..24.
//   points[p] > 0  => that many WHITE checkers on point p.
//   points[p] < 0  => that many BLACK checkers on point p (abs value).
//   BAR (0) is the sentinel source when entering from the bar.
//   OFF (25) is the sentinel destination when bearing off.

export const BAR = 0;
export const OFF = 25;

/** @typedef {"white" | "black"} Player */

/** @typedef {{ from: number, to: number, die: number }} Move */
/** @typedef {{ from: number, to: number, die: number, hit: boolean }} AppliedMove */
/** @typedef {{ points: number[], bar: { white: number, black: number }, off: { white: number, black: number } }} Board */
/** @typedef {object} GameState
 * @property {number[]} points
 * @property {{ white: number, black: number }} bar
 * @property {{ white: number, black: number }} off
 * @property {Player} turn
 * @property {"roll" | "move" | "gameover" | "doubleOffered"} phase
 * @property {number[]} dice
 * @property {number[]} remainingDice
 * @property {{ value: number, owner: Player | null }} cube
 * @property {"easy" | "medium" | "hard"} difficulty
 * @property {{ white: number, black: number }} score
 * @property {Player | null} winner
 * @property {"single" | "gammon" | "backgammon" | null} winType
 * @property {number} pointsWon
 * @property {Player | null} doubleOfferedBy
 * @property {string} message
 * @property {AppliedMove[]} history
 * @property {boolean} canDouble
 * @property {boolean} turnOver
 * @property {number} gamesPlayed
 */

/** The two-player identity: returns the other player.
 * @param {Player} p
 * @returns {Player}
 */
export function opponent(p) {
  return p === "white" ? "black" : "white";
}

/** Return +1 for white and -1 for black.
 * @param {Player} p
 * @returns {1 | -1}
 */
function sign(p) {
  return p === "white" ? 1 : -1;
}

/** Count of `player`'s checkers on point `p`.
 * @param {Board} b
 * @param {Player} player
 * @param {number} p
 */
function myCount(b, player, p) {
  const s = sign(player);
  const v = b.points[p] * s;
  return v > 0 ? v : 0;
}

/** The standard opening arrangement as a fresh points[] array (length 26, index 1..24 used).
 * @returns {number[]}
 */
export function startingPoints() {
  return [
    0, -2, 0, 0, 0, 0, 5, 0, 3, 0, 0, 0, -5,
    5, 0, 0, 0, -3, 0, -5, 0, 0, 0, 0, 2, 0,
  ];
}

/** A fresh GameState for a new game at the given difficulty (white to move, phase "roll").
 * @param {GameState["difficulty"]} difficulty
 * @returns {GameState}
 */
export function createGame(difficulty) {
  /** @type {GameState} */
  const g = {
    points: startingPoints(),
    bar: { white: 0, black: 0 },
    off: { white: 0, black: 0 },
    turn: "white",
    phase: "roll",
    dice: [],
    remainingDice: [],
    cube: { value: 1, owner: null },
    difficulty: difficulty || "medium",
    score: { white: 0, black: 0 },
    winner: null,
    winType: null,
    pointsWon: 0,
    doubleOfferedBy: null,
    message: "Your turn to roll.",
    history: [],
    canDouble: true,
    turnOver: false,
    gamesPlayed: 0,
  };
  return g;
}

/** Deep-copy a Board (points + bar + off) so callers can explore without mutating.
 * @param {Board} b
 * @returns {Board}
 */
export function cloneBoard(b) {
  return {
    points: b.points.slice(),
    bar: { white: b.bar.white, black: b.bar.black },
    off: { white: b.off.white, black: b.off.black },
  };
}

/** True when ALL of `player`'s checkers are in that player's home quadrant (none on the bar,
 *  none outside home). White home = points 1..6; black home = points 19..24.
 * @param {Board} b
 * @param {Player} player
 */
export function allInHome(b, player) {
  const s = sign(player);
  if (s === 1) {
    if (b.bar.white > 0) return false;
    for (let p = 7; p <= 24; p++) {
      if (b.points[p] > 0) return false;
    }
  } else {
    if (b.bar.black > 0) return false;
    for (let p = 1; p <= 18; p++) {
      if (b.points[p] < 0) return false;
    }
  }
  return true;
}

/** Return the farthest home point for `player` (white: highest point, black: lowest point).
 * @param {Board} b
 * @param {Player} player
 */
function homeHighPoint(b, player) {
  const s = sign(player);
  let extreme = 0;
  if (s === 1) {
    for (let p = 6; p >= 1; p--) {
      if (b.points[p] > 0) return p;
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      if (b.points[p] < 0) return p;
    }
  }
  return extreme;
}

/** Every legal single-checker move `player` could make using ONE die of value `die` from board
 *  `b`, as {from,to,die}. `from` may be BAR; `to` may be OFF.
 * @param {Board} b
 * @param {Player} player
 * @param {number} die
 * @returns {Move[]}
 */
export function singleMoves(b, player, die) {
  const s = sign(player);
  const bar = player === "white" ? b.bar.white : b.bar.black;
  const moves = [];

  // Bar entry has absolute priority.
  if (bar > 0) {
    const to = player === "white" ? 25 - die : die;
    if (to >= 1 && to <= 24) {
      const occ = b.points[to] * (-s);
      if (occ < 2) {
        // Bar checker lands on empty/own/blot.
        moves.push({ from: BAR, to, die });
      }
    }
    return moves;
  }

  const canBearOff = allInHome(b, player);
  const furthestHome = canBearOff ? homeHighPoint(b, player) : 0;

  for (let p = 1; p <= 24; p++) {
    const cnt = myCount(b, player, p);
    if (cnt === 0) continue;

    let to;
    let distance;
    if (player === "white") {
      to = p - die;
      distance = p;
    } else {
      to = p + die;
      distance = 25 - p;
    }

    // Normal in-board move.
    if (to >= 1 && to <= 24) {
      const occ = b.points[to] * (-s);
      if (occ < 2) {
        moves.push({ from: p, to, die });
      }
      continue;
    }

    // Bear-off candidate.
    if (!canBearOff) continue;

    if (die === distance) {
      moves.push({ from: p, to: OFF, die });
    } else if (die > distance && furthestHome === p) {
      // Overshoot bear-off allowed only from the farthest occupied home point.
      moves.push({ from: p, to: OFF, die });
    }
  }

  return moves;
}

/** Apply one single move to board `b` IN PLACE for `player`. Returns whether the move hit an
 *  opponent blot (sending it to the bar).
 * @param {Board} b
 * @param {Player} player
 * @param {Move} m
 * @returns {boolean}
 */
export function applyMove(b, player, m) {
  const s = sign(player);
  const opp = opponent(player);

  // Remove checker from source.
  if (m.from === BAR) {
    if (player === "white") b.bar.white -= 1;
    else b.bar.black -= 1;
  } else {
    b.points[m.from] -= s;
  }

  // Place checker on destination.
  if (m.to === OFF) {
    if (player === "white") b.off.white += 1;
    else b.off.black += 1;
    return false;
  }

  const destOcc = b.points[m.to] * (-s);
  let hit = false;
  if (destOcc === 1) {
    // Hit a blot.
    hit = true;
    b.points[m.to] += s; // remove the opponent blot from the point.
    if (opp === "white") b.bar.white += 1;
    else b.bar.black += 1;
  }
  b.points[m.to] += s;
  return hit;
}

/** Reverse a single applied move in place. Used for undo.
 * @param {Board} b
 * @param {Player} player
 * @param {AppliedMove} am
 */
function reverseMove(b, player, am) {
  const s = sign(player);
  const opp = opponent(player);

  // Remove from destination.
  if (am.to === OFF) {
    if (player === "white") b.off.white -= 1;
    else b.off.black -= 1;
  } else {
    b.points[am.to] -= s;
  }

  // Restore opponent blot if the move was a hit.
  if (am.hit) {
    b.points[am.to] -= s; // put opponent checker back on the point.
    if (opp === "white") b.bar.white -= 1;
    else b.bar.black -= 1;
  }

  // Put checker back on source.
  if (am.from === BAR) {
    if (player === "white") b.bar.white += 1;
    else b.bar.black += 1;
  } else {
    b.points[am.from] += s;
  }
}

/** The maximum number of dice from `dice` that `player` can legally consume from board `b`
 *  (searching all orderings). Doubles present as four dice.
 * @param {Board} b
 * @param {Player} player
 * @param {number[]} dice
 */
export function maxPlies(b, player, dice) {
  if (dice.length === 0) return 0;
  let best = 0;
  // Try each distinct die index.
  for (let i = 0; i < dice.length; i++) {
    const die = dice[i];
    const moves = singleMoves(b, player, die);
    if (moves.length === 0) continue;
    const rest = dice.slice(0, i).concat(dice.slice(i + 1));
    for (const m of moves) {
      const nb = cloneBoard(b);
      applyMove(nb, player, m);
      const got = 1 + maxPlies(nb, player, rest);
      if (got > best) best = got;
    }
  }
  return best;
}

/** Return unique die values present in `dice`, each paired with how many copies remain.
 * @param {number[]} dice
 */
function uniqueDice(dice) {
  const map = new Map();
  for (const d of dice) map.set(d, (map.get(d) || 0) + 1);
  return Array.from(map.entries()).map(([die, count]) => ({ die, count }));
}

/** The single moves `player` may legally choose RIGHT NOW given the remaining `dice`, honouring
 *  the rule that a player must use as many dice as possible.
 * @param {Board} b
 * @param {Player} player
 * @param {number[]} dice
 * @returns {Move[]}
 */
export function legalMovesNow(b, player, dice) {
  if (dice.length === 0) return [];
  const mp = maxPlies(b, player, dice);
  if (mp === 0) return [];

  // Special higher-die rule when only one of two dice can be played.
  if (dice.length === 2 && mp === 1) {
    const d1 = dice[0];
    const d2 = dice[1];
    const high = Math.max(d1, d2);
    const low = Math.min(d1, d2);
    const highMoves = singleMoves(b, player, high);
    if (highMoves.length > 0) return highMoves;
    return singleMoves(b, player, low);
  }

  const legal = [];
  const uniq = uniqueDice(dice);
  for (const { die, count } of uniq) {
    const moves = singleMoves(b, player, die);
    for (const m of moves) {
      const nb = cloneBoard(b);
      applyMove(nb, player, m);
      const rest = [];
      let used = false;
      for (const d of dice) {
        if (!used && d === die) {
          used = true;
          continue;
        }
        rest.push(d);
      }
      const future = maxPlies(nb, player, rest);
      if (future === mp - 1) {
        legal.push(m);
      }
    }
  }
  return legal;
}

/** Enumerate every maximal full-turn move sequence and its resulting board.
 * @param {Board} b
 * @param {Player} player
 * @param {number[]} dice
 */
export function allSequences(b, player, dice) {
  const target = maxPlies(b, player, dice);
  if (target === 0) return [{ board: cloneBoard(b), moves: [] }];

  /** @type {{ board: Board, moves: Move[] }[]} */
  const results = [];

  /** @param {Board} cb
   * @param {number[]} rem
   * @param {Move[]} seq
   */
  function dfs(cb, rem, seq) {
    if (rem.length === 0) {
      if (seq.length === target) results.push({ board: cloneBoard(cb), moves: seq.slice() });
      return;
    }
    let progress = false;
    const uniq = uniqueDice(rem);
    for (const { die, count } of uniq) {
      const moves = singleMoves(cb, player, die);
      for (const m of moves) {
        progress = true;
        const nb = cloneBoard(cb);
        applyMove(nb, player, m);
        const nextRem = [];
        let used = false;
        for (const d of rem) {
          if (!used && d === die) {
            used = true;
            continue;
          }
          nextRem.push(d);
        }
        dfs(nb, nextRem, seq.concat(m));
      }
    }
    if (!progress && seq.length === target) {
      results.push({ board: cloneBoard(cb), moves: seq.slice() });
    }
  }

  dfs(b, dice, []);

  // Dedupe by move sequence key to avoid identical entries from indistinguishable dice.
  const seen = new Set();
  const out = [];
  for (const r of results) {
    const key = r.moves.map((m) => `${m.from}->${m.to}:${m.die}`).join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(r);
  }
  return out;
}

/** The pip count for `player` on board `b` (checkers on the bar count as the maximum distance).
 * @param {Board} b
 * @param {Player} player
 */
export function pipCount(b, player) {
  let total = 0;
  if (player === "white") {
    total += b.bar.white * 25;
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] > 0) total += b.points[p] * p;
    }
  } else {
    total += b.bar.black * 25;
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] < 0) total += -b.points[p] * (25 - p);
    }
  }
  return total;
}

/** Whether `player` has borne off all 15 checkers, and if so the classification of the win.
 * @param {Board} b
 * @param {Player} player
 */
export function checkWin(b, player) {
  const off = player === "white" ? b.off.white : b.off.black;
  if (off < 15) return { won: false, type: null };

  const opp = opponent(player);
  const oppOff = opp === "white" ? b.off.white : b.off.black;
  if (oppOff >= 1) return { won: true, type: "single" };

  // Opponent has not borne off. Check bar and winner's home for backgammon.
  const oppBar = opp === "white" ? b.bar.white : b.bar.black;
  if (oppBar > 0) return { won: true, type: "backgammon" };

  let inWinnerHome = false;
  if (player === "white") {
    for (let p = 1; p <= 6; p++) {
      if (b.points[p] < 0) { inWinnerHome = true; break; }
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      if (b.points[p] > 0) { inWinnerHome = true; break; }
    }
  }
  if (inWinnerHome) return { won: true, type: "backgammon" };
  return { won: true, type: "gammon" };
}

