input.content:
// Backgammon AI: move selection (easy/medium/hard) + doubling-cube reasoning.
import {
  allSequences,
  cloneBoard,
  pipCount,
  opponent,
  allInHome,
} from "./game.ts";

/** @typedef {import("./game.ts").Board} Board */
/** @typedef {import("./game.ts").Move} Move */
/** @typedef {import("./game.ts").Player} Player */
/** @typedef {{ moves: Move[], board: Board }} AiMoveResult */
/** @typedef {{ action: "double" | "no-double", reasoning: string }} CubeDecision */

/** Return +1 for white, -1 for black.
 * @param {Player} p
 */
function sign(p) {
  return p === "white" ? 1 : -1;
}

/** Count checkers of `player` on point `p`.
 * @param {Board} b
 * @param {Player} player
 * @param {number} p
 */
function myCount(b, player, p) {
  const s = sign(player);
  const v = b.points[p] * s;
  return v > 0 ? v : 0;
}

/** Count made points (2+ checkers) in `player`'s home board.
 * @param {Board} b
 * @param {Player} player
 */
function homeBoardStrength(b, player) {
  const s = sign(player);
  let made = 0;
  if (player === "white") {
    for (let p = 1; p <= 6; p++) if (b.points[p] >= 2) made++;
  } else {
    for (let p = 19; p <= 24; p++) if (b.points[p] <= -2) made++;
  }
  return made;
}

/** Count all checkers in `player`'s home board.
 * @param {Board} b
 * @param {Player} player
 */
function homeCheckers(b, player) {
  let n = 0;
  if (player === "white") {
    for (let p = 1; p <= 6; p++) if (b.points[p] > 0) n += b.points[p];
  } else {
    for (let p = 19; p <= 24; p++) if (b.points[p] < 0) n += -b.points[p];
  }
  return n;
}

/** Count own blots (single checkers) on the board.
 * @param {Board} b
 * @param {Player} player
 */
function blotCount(b, player) {
  const s = sign(player);
  let n = 0;
  for (let p = 1; p <= 24; p++) {
    if (b.points[p] * s === 1) n++;
  }
  return n;
}

/** Count opponent blots (single checkers) — good targets.
 * @param {Board} b
 * @param {Player} player
 */
function opponentBlotCount(b, player) {
  return blotCount(b, opponent(player));
}

/** Length of the longest prime (consecutive made points).
 * @param {Board} b
 * @param {Player} player
 */
function longestPrime(b, player) {
  const s = sign(player);
  let best = 0;
  let cur = 0;
  for (let p = 1; p <= 24; p++) {
    if (b.points[p] * s >= 2) {
      cur++;
      if (cur > best) best = cur;
    } else {
      cur = 0;
    }
  }
  return best;
}

/** A scalar quality score of board `b` from `player`'s perspective (higher = better for player).
 * @param {Board} b
 * @param {Player} player
 */
export function evaluate(b, player) {
  const opp = opponent(player);
  const myPip = pipCount(b, player);
  const oppPip = pipCount(b, opp);
  const lead = oppPip - myPip;

  const myOff = player === "white" ? b.off.white : b.off.black;
  const oppOff = opp === "white" ? b.off.white : b.off.black;
  const myBar = player === "white" ? b.bar.white : b.bar.black;
  const oppBar = opp === "white" ? b.bar.white : b.bar.black;

  let score = 0;

  // Pip lead is the dominant signal.
  score += lead * 3.0;

  // Borne-off checkers are extremely valuable.
  score += myOff * 18.0;
  score -= oppOff * 18.0;

  // Bar checkers.
  score -= myBar * 12.0;
  score += oppBar * 12.0;

  // Home-board strength and priming.
  score += homeBoardStrength(b, player) * 4.0;
  score -= homeBoardStrength(b, opp) * 4.0;
  score += homeCheckers(b, player) * 1.5;
  score -= homeCheckers(b, opp) * 1.5;
  score += longestPrime(b, player) * 2.0;
  score -= longestPrime(b, opp) * 2.0;

  // Blot danger / targets.
  score -= blotCount(b, player) * 3.5;
  score += opponentBlotCount(b, player) * 3.0;

  // Race bonus once bearing off is possible.
  if (allInHome(b, player)) score += myOff * 3.0;
  if (allInHome(b, opp)) score -= oppOff * 3.0;

  return score;
}

/** All 21 equally-weighted dice rolls (two distinct dice + doubles).
 * @returns {{ dice: number[], weight: number }[]}
 */
function allRolls() {
  const rolls = [];
  for (let i = 1; i <= 6; i++) {
    for (let j = i; j <= 6; j++) {
      const weight = i === j ? 1 : 2;
      const dice = i === j ? [i, i, i, i] : [i, j];
      rolls.push({ dice, weight });
    }
  }
  return rolls;
}

/** Choose the best sequence by immediate evaluation.
 * @param {{ board: Board, moves: Move[] }[]} seqs
 * @param {Player} player
 */
function pickBest(seqs, player) {
  let best = seqs[0];
  let bestScore = evaluate(best.board, player);
  for (let i = 1; i < seqs.length; i++) {
    const s = evaluate(seqs[i].board, player);
    if (s > bestScore) {
      bestScore = s;
      best = seqs[i];
    }
  }
  return best;
}

/** Choose the AI's full-turn move sequence for the given `dice` at `difficulty`.
 * @param {Board} b
 * @param {Player} player
 * @param {number[]} dice
 * @param {"easy" | "medium" | "hard"} difficulty
 * @returns {AiMoveResult}
 */
export function chooseMoves(b, player, dice, difficulty) {
  const seqs = allSequences(b, player, dice);
  if (seqs.length === 0) {
    return { moves: [], board: cloneBoard(b) };
  }

  if (difficulty === "easy") {
    const r = seqs[Math.floor(Math.random() * seqs.length)];
    return { moves: r.moves, board: cloneBoard(r.board) };
  }

  if (difficulty === "medium") {
    const best = pickBest(seqs, player);
    return { moves: best.moves, board: cloneBoard(best.board) };
  }

  // Hard: one-ply lookahead using expected value over opponent replies.
  const opp = opponent(player);
  const rolls = allRolls();
  let bestSeq = seqs[0];
  let bestScore = -Infinity;

  for (const seq of seqs) {
    let expected = 0;
    let totalWeight = 0;
    for (const { dice: oppDice, weight } of rolls) {
      totalWeight += weight;
      const oppSeqs = allSequences(seq.board, opp, oppDice);
      if (oppSeqs.length === 0) {
        expected += evaluate(seq.board, player) * weight;
        continue;
      }
      const oppBest = pickBest(oppSeqs, opp);
      expected += evaluate(oppBest.board, player) * weight;
    }
    expected /= totalWeight;
    // Blend with immediate evaluation so very strong immediate moves aren't missed.
    const immediate = evaluate(seq.board, player);
    const blended = expected * 0.7 + immediate * 0.3;
    if (blended > bestScore) {
      bestScore = blended;
      bestSeq = seq;
    }
  }

  return { moves: bestSeq.moves, board: cloneBoard(bestSeq.board) };
}

/** Estimate `player`'s probability of winning from board `b`, in [0,1].
 * @param {Board} b
 * @param {Player} player
 */
export function winProbability(b, player) {
  const myPip = pipCount(b, player);
  const oppPip = pipCount(b, opponent(player));
  const lead = oppPip - myPip;
  const k = 30;
  const p = 1 / (1 + Math.exp(-lead / k));
  // Clamp for numerical safety.
  if (p <= 0) return 0.00001;
  if (p >= 1) return 0.99999;
  return p;
}

/** Decide whether the AI (`player`) should OFFER a double.
 * @param {Board} b
 * @param {Player} player
 * @param {{ value: number, owner: Player | null }} cube
 * @param {"easy" | "medium" | "hard"} difficulty
 * @returns {CubeDecision}
 */
export function shouldAiDouble(b, player, cube, difficulty) {
  // Easy never offers.
  if (difficulty === "easy") {
    return { action: "no-double", reasoning: "Easy AI never doubles." };
  }

  // Only double when the AI owns or the cube is centered.
  if (cube.owner && cube.owner !== player) {
    return { action: "no-double", reasoning: "Opponent owns the cube." };
  }

  const p = winProbability(b, player);
  const lower = difficulty === "hard" ? 0.68 : 0.72;

  if (p > 0.9) {
    return { action: "no-double", reasoning: "Too good to double; play on for gammon." };
  }
  if (p >= lower) {
    return { action: "double", reasoning: `Win probability ${(p * 100).toFixed(1)}% is inside the double window.` };
  }
  return { action: "no-double", reasoning: `Win probability ${(p * 100).toFixed(1)}% is below the double threshold.` };
}

/** Decide whether the AI (`player`) should ACCEPT a double the human just offered.
 * @param {Board} b
 * @param {Player} player
 * @param {"easy" | "medium" | "hard"} difficulty
 * @returns {CubeDecision}
 */
export function shouldAiAccept(b, player, difficulty) {
  const p = winProbability(b, player);
  const takePoint = difficulty === "easy" ? 0.32 : difficulty === "medium" ? 0.27 : 0.24;
  if (p >= takePoint) {
    return { action: "double", reasoning: `Win probability ${(p * 100).toFixed(1)}% is above the take point.` };
  }
  return { action: "no-double", reasoning: `Win probability ${(p * 100).toFixed(1)}% is too low to take.` };
}

