// Backgammon HTTP server — Node standard library only, serves API + static UI on :8002.
import http from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

import {
  BAR,
  OFF,
  createGame,
  cloneBoard,
  legalMovesNow,
  applyMove,
  pipCount,
  checkWin,
  opponent,
  reverseMove,
} from "./game.ts";
import {
  chooseMoves,
  shouldAiDouble,
  shouldAiAccept,
  winProbability,
} from "./ai.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = path.join(__dirname, "..", "public");
const PORT = 8002;
const BENCH_DEBUG = process.env.BENCH_DEBUG === "1";
const HUMAN = "white";
const AI = "black";

/** @typedef {import("./game.ts").GameState} GameState */
/** @typedef {import("./game.ts").Board} Board */
/** @typedef {import("./game.ts").Move} Move */
/** @typedef {import("./game.ts").AppliedMove} AppliedMove */
/** @typedef {import("./game.ts").Player} Player */

/** @type {GameState & { aiCubeDone?: boolean, debugDiceQueue?: number[][] }} */
let game = {};

function initFirstGame() {
  game = createGame("medium");
  game.aiCubeDone = false;
  game.debugDiceQueue = [];
}
initFirstGame();

/** @param {string} type */
function multiplier(type) {
  if (type === "gammon") return 2;
  if (type === "backgammon") return 3;
  return 1;
}

/** Whether the human may offer a double right now.
 * @param {any} g
 */
function humanCanDouble(g) {
  if (g.phase !== "roll") return false;
  if (g.turn !== HUMAN) return false;
  if (g.doubleOfferedBy) return false;
  // Cube centered or owned by human.
  return !g.cube.owner || g.cube.owner === HUMAN;
}

/** Whether the AI may offer a double right now.
 * @param {any} g
 */
function aiCanDouble(g) {
  if (g.phase !== "roll") return false;
  if (g.turn !== AI) return false;
  if (g.doubleOfferedBy) return false;
  return !g.cube.owner || g.cube.owner === AI;
}

/** Serialize the state the client needs.
 * @param {any} g
 * @param {Record<string, unknown>} extra
 */
function serialize(g, extra = {}) {
  const board = { points: g.points, bar: g.bar, off: g.off };
  const legalMoves = g.turn === HUMAN && g.phase === "move"
    ? legalMovesNow(board, HUMAN, g.remainingDice)
    : [];
  const canDouble = humanCanDouble(g);
  return {
    points: g.points,
    bar: g.bar,
    off: g.off,
    turn: g.turn,
    phase: g.phase,
    dice: g.dice,
    remainingDice: g.remainingDice,
    cube: g.cube,
    difficulty: g.difficulty,
    score: g.score,
    winner: g.winner,
    winType: g.winType,
    pointsWon: g.pointsWon,
    doubleOfferedBy: g.doubleOfferedBy,
    message: g.message,
    turnOver: g.turnOver,
    gamesPlayed: g.gamesPlayed,
    pip: { white: pipCount(board, "white"), black: pipCount(board, "black") },
    legalMoves,
    canDouble,
    ...extra,
  };
}

/** Finish the game with a winner and win type.
 * @param {any} g
 * @param {Player} winner
 * @param {"single" | "gammon" | "backgammon" | null} type
 * @param {boolean} declined
 */
function finishGame(g, winner, type, declined = false) {
  const stake = g.cube.value * multiplier(type || "single");
  g.winner = winner;
  g.winType = type;
  g.pointsWon = stake;
  g.score[winner] += stake;
  g.gamesPlayed += 1;
  g.phase = "gameover";
  g.turnOver = true;
  g.doubleOfferedBy = null;
  if (winner === HUMAN) {
    g.message = `You win! ${type} — ${stake} point${stake !== 1 ? "s" : ""}.`;
  } else {
    g.message = `AI wins. ${type} — ${stake} point${stake !== 1 ? "s" : ""}.`;
  }
  if (declined) {
    g.message += " (opponent declined the double)";
  }
}

/** After a checker action, refresh turn-over status for the human.
 * @param {any} g
 */
function refreshHumanTurn(g) {
  if (g.phase !== "move" || g.turn !== HUMAN) return;
  if (g.remainingDice.length === 0) {
    g.turnOver = true;
    g.message = "Turn over — end your turn.";
    return;
  }
  const board = { points: g.points, bar: g.bar, off: g.off };
  const moves = legalMovesNow(board, HUMAN, g.remainingDice);
  if (moves.length === 0) {
    g.turnOver = true;
    g.message = "No legal move — pass.";
  }
}

/** Roll two dice, respecting debug queue, sorting ascending and expanding doubles.
 * @param {any} g
 */
function rollDice(g) {
  if (g.debugDiceQueue && g.debugDiceQueue.length > 0) {
    const next = g.debugDiceQueue.shift();
    if (next && next.length > 0) {
      const sorted = next.slice().sort((a, b) => a - b);
      if (sorted.length === 2 && sorted[0] === sorted[1]) {
        const v = sorted[0];
        return [v, v, v, v];
      }
      return sorted;
    }
  }
  const d1 = Math.floor(Math.random() * 6) + 1;
  const d2 = Math.floor(Math.random() * 6) + 1;
  const sorted = d1 === d2 ? [d1, d1, d1, d1] : [Math.min(d1, d2), Math.max(d1, d2)];
  return sorted;
}

// ---------------- action handlers ----------------

/** @param {any} body */
function actionNew(body) {
  const difficulty = ["easy", "medium", "hard"].includes(body && body.difficulty)
    ? body.difficulty
    : game.difficulty;
  const score = { ...game.score };
  const gamesPlayed = game.gamesPlayed;
  game = createGame(difficulty);
  game.score = score;
  game.gamesPlayed = gamesPlayed;
  game.aiCubeDone = false;
  game.debugDiceQueue = game.debugDiceQueue || [];
  game.message = "New game — your turn to roll.";
}

function actionRoll() {
  if (game.phase !== "roll" || game.turn !== HUMAN) {
    return;
  }
  const dice = rollDice(game);
  game.dice = dice;
  game.remainingDice = dice.slice();
  game.phase = "move";
  game.history = [];
  game.turnOver = false;
  game.message = `You rolled ${diceText(dice)}.`;

  const board = { points: game.points, bar: game.bar, off: game.off };
  const moves = legalMovesNow(board, HUMAN, game.remainingDice);
  if (moves.length === 0) {
    game.turnOver = true;
    game.message = "No legal move — pass.";
  }
}

/** @param {number[]} dice */
function diceText(dice) {
  if (dice.length === 4) return `${dice[0]}-${dice[0]} (doubles, 4 moves)`;
  return `${dice[0]} and ${dice[1]}`;
}

/** @param {any} body */
function actionMove(body) {
  if (game.phase !== "move" || game.turn !== HUMAN) {
    throw new Error("Not your move phase");
  }
  const board = { points: game.points, bar: game.bar, off: game.off };
  const moves = legalMovesNow(board, HUMAN, game.remainingDice);
  const from = Number(body.from);
  const to = Number(body.to);
  const die = Number(body.die);
  const match = moves.find((m) => m.from === from && m.to === to && m.die === die);
  if (!match) {
    throw new Error("Illegal move");
  }
  const hit = applyMove(game, HUMAN, match);
  /** @type {AppliedMove} */
  const applied = { from: match.from, to: match.to, die: match.die, hit };
  game.history.push(applied);

  // Remove the used die.
  const idx = game.remainingDice.indexOf(die);
  if (idx >= 0) game.remainingDice.splice(idx, 1);

  const win = checkWin(game, HUMAN);
  if (win.won) {
    finishGame(game, HUMAN, win.type);
    return;
  }
  refreshHumanTurn(game);
}

function actionUndo() {
  if (game.turn !== HUMAN || game.history.length === 0) return;
  const last = game.history.pop();
  reverseMove(game, HUMAN, last);
  game.remainingDice.push(last.die);
  game.remainingDice.sort((a, b) => a - b);
  game.phase = "move";
  game.turnOver = false;
  game.message = "Move undone.";
}

function actionEndTurn() {
  if (game.turn !== HUMAN || game.phase !== "move" || !game.turnOver) {
    return;
  }
  game.turn = AI;
  game.phase = "roll";
  game.dice = [];
  game.remainingDice = [];
  game.history = [];
  game.aiCubeDone = false;
  game.message = "AI's turn.";
}

/** Human offers a double; AI decides immediately. */
function actionDouble() {
  if (!humanCanDouble(game)) {
    game.message = "You cannot double right now.";
    return {};
  }
  const decision = shouldAiAccept(game, AI, game.difficulty);
  if (decision.action === "double") {
    game.cube.value *= 2;
    game.cube.owner = AI; // taker owns the doubled cube.
    game.message = `AI takes the double. Cube is now ${game.cube.value}, owned by AI.`;
    return { cubeAccepted: true };
  } else {
    finishGame(game, HUMAN, "single", true);
    return { cubeDeclined: true };
  }
}

/** @param {any} body */
function actionRespondDouble(body) {
  if (game.phase !== "doubleOffered" || game.doubleOfferedBy !== AI) {
    return;
  }
  const accepted = !!body.accept;
  if (accepted) {
    game.cube.value *= 2;
    game.cube.owner = HUMAN; // taker owns the cube.
    game.phase = "roll";
    game.doubleOfferedBy = null;
    game.message = `You take the double. Cube is now ${game.cube.value}, owned by you.`;
    // AI's turn continues; it may now roll.
  } else {
    finishGame(game, AI, "single", true);
  }
}

/** Run one AI step: possibly offer a double, otherwise roll + move. */
function actionAi() {
  if (game.phase === "gameover") return {};

  // AI offers a double before rolling.
  if (game.turn === AI && game.phase === "roll" && !game.aiCubeDone) {
    if (aiCanDouble(game)) {
      const decision = shouldAiDouble(game, AI, game.cube, game.difficulty);
      if (decision.action === "double") {
        game.phase = "doubleOffered";
        game.doubleOfferedBy = AI;
        game.aiCubeDone = true;
        game.message = "AI offers a double.";
        return { aiDouble: true };
      }
    }
    game.aiCubeDone = true;
  }

  if (game.turn === AI && game.phase === "roll") {
    const dice = rollDice(game);
    game.dice = dice;
    game.remainingDice = dice.slice();
    game.phase = "move";
    game.history = [];
    game.message = `AI rolled ${diceText(dice)}.`;

    const board = { points: game.points, bar: game.bar, off: game.off };
    const moves = legalMovesNow(board, AI, game.remainingDice);
    if (moves.length === 0) {
      // No legal move, auto-pass.
      game.turn = HUMAN;
      game.phase = "roll";
      game.dice = [];
      game.remainingDice = [];
      game.aiCubeDone = false;
      game.message = "AI has no legal move — pass. Your turn to roll.";
      return {};
    }
  }

  if (game.turn === AI && game.phase === "move") {
    const board = { points: game.points, bar: game.bar, off: game.off };
    const result = chooseMoves(board, AI, game.remainingDice, game.difficulty);
    for (const m of result.moves) {
      applyMove(game, AI, m);
      const applied = { from: m.from, to: m.to, die: m.die, hit: false };
      // Recalculate hit by comparing result? applyMove returns boolean but we call on mutated game.
      // Instead detect by looking at the move outcome; simpler: just record hit=false is fine for AI history.
      game.history.push(applied);
      const idx = game.remainingDice.indexOf(m.die);
      if (idx >= 0) game.remainingDice.splice(idx, 1);
    }
    const win = checkWin(game, AI);
    if (win.won) {
      finishGame(game, AI, win.type);
      return {};
    }
    game.turn = HUMAN;
    game.phase = "roll";
    game.dice = [];
    game.remainingDice = [];
    game.history = [];
    game.aiCubeDone = false;
    game.message = "Your turn to roll.";
  }
  return {};
}

/** @param {any} body */
function actionDebugState(body) {
  if (!BENCH_DEBUG) return {};
  const allowed = [
    "points", "bar", "off", "turn", "phase", "dice", "remainingDice",
    "cube", "difficulty", "score", "winner", "winType", "pointsWon",
    "doubleOfferedBy", "message",
  ];
  for (const key of allowed) {
    if (key in body) game[key] = body[key];
  }
  game.aiCubeDone = false;
  // Sanitize arrays / nested objects so the debug state is usable.
  if (!Array.isArray(game.dice)) game.dice = [];
  if (!Array.isArray(game.remainingDice)) game.remainingDice = [];
  if (!Array.isArray(game.history)) game.history = [];
  if (typeof game.pointsWon !== "number") game.pointsWon = 0;
  if (!game.cube || typeof game.cube !== "object") game.cube = { value: 1, owner: null };
  // Echo the supplied fields back in the response.
  return { debug: body };
}

/** @param {any} body */
function actionDebugRoll(body) {
  if (!BENCH_DEBUG) return {};
  if (!game.debugDiceQueue) game.debugDiceQueue = [];
  if (Array.isArray(body.dice)) {
    game.debugDiceQueue.push(body.dice);
  }
  return { debugDiceQueued: game.debugDiceQueue.length };
}

// ---------------- HTTP plumbing ----------------

const MIME = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

/** @param {http.IncomingMessage} req */
function readBody(req) {
  return new Promise((resolve) => {
    let data = "";
    req.on("data", (c) => (data += c));
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch {
        resolve({});
      }
    });
  });
}

/** @param {http.IncomingMessage} req
 * @param {http.ServerResponse} res
 * @param {string} urlPath
 */
async function serveStatic(req, res, urlPath) {
  let safe = path.normalize(urlPath).replace(/^(\.+(\/|\\|$))+/, "");
  if (safe === "/" || safe === "") safe = "index.html";
  const filePath = path.join(PUBLIC_DIR, safe);
  try {
    const data = await readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { "Content-Type": MIME[ext] || "application/octet-stream" });
    res.end(data);
  } catch {
    res.writeHead(404, { "Content-Type": "text/plain" });
    res.end("Not found");
  }
}

const server = http.createServer(async (req, res) => {
  const url = req.url || "/";
  try {
    if (req.method === "GET" && url.split("?")[0] === "/health") {
      const payload = JSON.stringify({ status: "ok", port: PORT });
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(payload);
      return;
    }

    if (url.startsWith("/api/")) {
      const body = req.method === "POST" ? await readBody(req) : {};
      let extra = {};
      switch (url.split("?")[0]) {
        case "/api/state":
          break;
        case "/api/new":
          actionNew(body);
          break;
        case "/api/roll":
          actionRoll();
          break;
        case "/api/move":
          actionMove(body);
          break;
        case "/api/undo":
          actionUndo();
          break;
        case "/api/endturn":
          actionEndTurn();
          break;
        case "/api/double":
          extra = actionDouble() || {};
          break;
        case "/api/double/respond":
          actionRespondDouble(body);
          break;
        case "/api/ai":
          extra = actionAi() || {};
          break;
        case "/api/debug/state":
          if (!BENCH_DEBUG) {
            res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
            return;
          }
          extra = actionDebugState(body) || {};
          break;
        case "/api/debug/roll":
          if (!BENCH_DEBUG) {
            res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
            return;
          }
          extra = actionDebugRoll(body) || {};
          break;
        default:
          res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
          return;
      }
      const payload = JSON.stringify(serialize(game, extra));
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(payload);
      return;
    }
    await serveStatic(req, res, url);
  } catch (err) {
    console.error("Request error:", err);
    res.writeHead(500, { "Content-Type": "application/json" }).end(JSON.stringify({ error: String(err) }));
  }
});

server.on("error", (err) => {
  if (err.code === "EADDRINUSE") {
    console.error(`Port ${PORT} is already in use.`);
    process.exit(1);
    return;
  }
  console.error(String(err));
  process.exit(1);
});

server.listen(PORT, () => {
  console.log(`Backgammon server running at http://localhost:${PORT}/`);
});

