input.content:
// Backgammon core engine — pure logic, no I/O.
// Board convention:
//   Points are numbered 1..24, stored in `points[1..24]` (index 0 and 25 are sentinels).
//   White (the human) moves HIGH -> LOW (24 -> 1). White home = 1..6.
//   Black (the AI) moves LOW -> HIGH (1 -> 24). Black home = 19..24.
//   points[p] > 0  => that many WHITE checkers on point p.
//   points[p] < 0  => that many BLACK checkers on point p (abs value).
//   Bearing off: white bears off past point 1 (to 0 = OFF); black past 24 (to 25 = OFF).

export type Player = "white" | "black";

export const BAR = 0; // sentinel "from" for entering from the bar
export const OFF = 25; // sentinel "to" for bearing off

export interface Move {
  from: number;
  to: number;
  die: number;
}

export interface AppliedMove extends Move {
  hit: boolean;
}

export interface Board {
  points: number[];
  bar: { white: number; black: number };
  off: { white: number; black: number };
}

export interface GameState {
  points: number[];
  bar: { white: number; black: number };
  off: { white: number; black: number };
  turn: Player;
  phase: "roll" | "move" | "gameover" | "doubleOffered";
  dice: number[];
  remainingDice: number[];
  cube: { value: number; owner: Player | null };
  difficulty: "easy" | "medium" | "hard";
  score: { white: number; black: number };
  winner: Player | null;
  winType: "single" | "gammon" | "backgammon" | null;
  pointsWon: number;
  doubleOfferedBy: Player | null;
  message: string;
  history: AppliedMove[];
  canDouble: boolean;
  turnOver: boolean;
  gamesPlayed: number;
}

/** The two-player identity: returns the other player. */
export function opponent(p: Player): Player {
  return p === "white" ? "black" : "white";
}

/** The standard opening arrangement as a fresh points[] array (length 26, index 1..24 used). */
export function startingPoints(): number[] {
  return [0, -2, 0, 0, 0, 0, 5, 0, 3, 0, 0, 0, -5, 5, 0, 0, 0, -3, 0, -5, 0, 0, 0, 0, 2, 0];
}

/** A fresh GameState for a new game at the given difficulty (white to move, phase "roll"). */
export function createGame(difficulty: GameState["difficulty"]): GameState {
  return {
    points: startingPoints(),
    bar: { white: 0, black: 0 },
    off: { white: 0, black: 0 },
    turn: "white",
    phase: "roll",
    dice: [],
    remainingDice: [],
    cube: { value: 1, owner: null },
    difficulty,
    score: { white: 0, black: 0 },
    winner: null,
    winType: null,
    pointsWon: 0,
    doubleOfferedBy: null,
    message: "New game — white to roll.",
    history: [],
    canDouble: true,
    turnOver: false,
    gamesPlayed: 0,
  };
}

/** Deep-copy a Board (points + bar + off) so callers can explore without mutating. */
export function cloneBoard(b: Board): Board {
  return {
    points: [...b.points],
    bar: { white: b.bar.white, black: b.bar.black },
    off: { white: b.off.white, black: b.off.black },
  };
}

/** True when ALL of `player`'s checkers are in that player's home quadrant. */
export function allInHome(b: Board, player: Player): boolean {
  if (b.bar[player] > 0) return false;
  if (player === "white") {
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] > 0 && p > 6) return false;
    }
  } else {
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] < 0 && p < 19) return false;
    }
  }
  return true;
}

function removeOneDie(dice: number[], die: number): number[] {
  const copy = [...dice];
  const idx = copy.indexOf(die);
  if (idx >= 0) copy.splice(idx, 1);
  return copy;
}

function highestHomePoint(b: Board, player: Player): number | null {
  if (player === "white") {
    for (let p = 6; p >= 1; p--) {
      if (b.points[p] > 0) return p;
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      if (b.points[p] < 0) return p;
    }
  }
  return null;
}

/** Every legal single-checker move `player` could make using ONE die of value `die`. */
export function singleMoves(b: Board, player: Player, die: number): Move[] {
  const sign = player === "white" ? 1 : -1;
  const oppSign = -sign;
  const moves: Move[] = [];

  // Bar entry takes precedence over all other moves.
  if (b.bar[player] > 0) {
    const entry = player === "white" ? 25 - die : die;
    const occupant = b.points[entry] * oppSign;
    if (occupant < 2) {
      moves.push({ from: BAR, to: entry, die });
    }
    return moves;
  }

  for (let p = 1; p <= 24; p++) {
    if (b.points[p] * sign <= 0) continue;
    const to = player === "white" ? p - die : p + die;
    if (to >= 1 && to <= 24) {
      if (b.points[to] * oppSign < 2) {
        moves.push({ from: p, to, die });
      }
    } else {
      // Bearing off.
      if (!allInHome(b, player)) continue;
      const distance = player === "white" ? p : 25 - p;
      if (die === distance) {
        moves.push({ from: p, to: OFF, die });
      } else if (die > distance) {
        const highest = highestHomePoint(b, player);
        if (highest === p) {
          moves.push({ from: p, to: OFF, die });
        }
      }
    }
  }
  return moves;
}

/** Apply one single move to board `b` IN PLACE for `player`. Returns whether the move hit a blot. */
export function applyMove(b: Board, player: Player, m: Move): boolean {
  const sign = player === "white" ? 1 : -1;
  const opp = opponent(player);
  let hit = false;

  if (m.from === BAR) {
    b.bar[player]--;
  } else {
    b.points[m.from] -= sign;
  }

  if (m.to === OFF) {
    b.off[player]++;
    return false;
  }

  // Hitting an opponent blot.
  if (b.points[m.to] * (-sign) === 1) {
    b.points[m.to] = 0;
    b.bar[opp]++;
    hit = true;
  }

  b.points[m.to] += sign;
  return hit;
}

/** The maximum number of dice from `dice` that `player` can legally consume. */
export function maxPlies(b: Board, player: Player, dice: number[]): number {
  if (dice.length === 0) return 0;
  let best = 0;
  const seen = new Set<number>();
  for (let i = 0; i < dice.length; i++) {
    const die = dice[i];
    if (seen.has(die)) continue;
    seen.add(die);
    const moves = singleMoves(b, player, die);
    for (const m of moves) {
      const nb = cloneBoard(b);
      applyMove(nb, player, m);
      const rest = removeOneDie(dice, die);
      const sub = maxPlies(nb, player, rest);
      best = Math.max(best, 1 + sub);
    }
  }
  return best;
}

/** The single moves `player` may legally choose right now given the remaining dice. */
export function legalMovesNow(b: Board, player: Player, dice: number[]): Move[] {
  if (dice.length === 0) return [];
  const best = maxPlies(b, player, dice);
  if (best === 0) return [];

  const moves: Move[] = [];
  const seenDice = new Set<number>();
  for (let i = 0; i < dice.length; i++) {
    const die = dice[i];
    if (seenDice.has(die)) continue;
    seenDice.add(die);
    const candidates = singleMoves(b, player, die);
    for (const m of candidates) {
      const rest = removeOneDie(dice, die);
      const nb = cloneBoard(b);
      applyMove(nb, player, m);
      const sub = maxPlies(nb, player, rest);
      if (1 + sub === best) {
        moves.push(m);
      }
    }
  }

  // REQ-HIGHER-DIE: when only one of two distinct dice can be played, it must be the higher one.
  if (best === 1 && dice.length === 2 && dice[0] !== dice[1]) {
    const higher = Math.max(dice[0], dice[1]);
    const hasHigher = moves.some((m) => m.die === higher);
    if (hasHigher) {
      return moves.filter((m) => m.die === higher);
    }
  }
  return moves;
}

/** Generate all legal full-turn move sequences and their resulting boards. */
export function allSequences(
  b: Board,
  player: Player,
  dice: number[],
): { board: Board; moves: Move[] }[] {
  const results: { board: Board; moves: Move[] }[] = [];

  function recurse(cur: Board, rem: number[], seq: Move[]) {
    if (rem.length === 0) {
      results.push({ board: cloneBoard(cur), moves: [...seq] });
      return;
    }
    let progress = false;
    const seen = new Set<number>();
    for (let i = 0; i < rem.length; i++) {
      const die = rem[i];
      if (seen.has(die)) continue;
      seen.add(die);
      const moves = singleMoves(cur, player, die);
      if (moves.length > 0) progress = true;
      for (const m of moves) {
        const nb = cloneBoard(cur);
        applyMove(nb, player, m);
        recurse(nb, rem.filter((_, j) => j !== i), [...seq, m]);
      }
    }
    if (!progress) {
      results.push({ board: cloneBoard(cur), moves: [...seq] });
    }
  }

  recurse(b, dice, []);
  return results;
}

/** The pip count for `player` on board `b` (bar checkers count as the maximum distance 25). */
export function pipCount(b: Board, player: Player): number {
  let count = 0;
  if (player === "white") {
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] > 0) count += p * b.points[p];
    }
    count += b.bar.white * 25;
  } else {
    for (let p = 1; p <= 24; p++) {
      if (b.points[p] < 0) count += (25 - p) * (-b.points[p]);
    }
    count += b.bar.black * 25;
  }
  return count;
}

/** Whether `player` has borne off all 15 checkers, and the classification of the win. */
export function checkWin(b: Board, player: Player): { won: boolean; type: "single" | "gammon" | "backgammon" | null } {
  if (b.off[player] < 15) return { won: false, type: null };
  const loser = opponent(player);
  if (b.off[loser] >= 1) return { won: true, type: "single" };

  const loserOnBar = b.bar[loser] > 0;
  let loserInWinnersHome = false;
  if (player === "white") {
    for (let p = 1; p <= 6; p++) {
      if (b.points[p] < 0) loserInWinnersHome = true;
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      if (b.points[p] > 0) loserInWinnersHome = true;
    }
  }

  if (loserOnBar || loserInWinnersHome) return { won: true, type: "backgammon" };
  return { won: true, type: "gammon" };
}

