```
export function legalMovesNow(b:Board, player:Player, dice:number[]): Move[] {
   if (dice.length===0) return [];
   const moves: Move[] = [];
   const distinct = [...new Set(dice)];
   const max = maxPlies(b, player, dice);
   if (max === 0) return [];
   for (const d of distinct) {
     // for each possible single move using die d
     for (const m of singleMoves(b, player, d)) {
       // test if this move as next can achieve max plies (i.e., maxPlies(b', player, remainingWithoutD) === max-1)
       const rem = removeOne(dice, d);
       const b2 = cloneBoard(b);
       applyMove(b2, player, m);
       const sub = maxPlies(b2, player, rem);
       if (1 + sub === max) moves.push(m);
     }
   }
   // For distinct dice with max == 1, must play higher die if both dice can be played.
   if (max === 1 && dice.length === 2 && distinct.length === 2 && distinct[0] !== distinct[1]) {
      const higher = Math.max(...distinct);
      // filter moves.die === higher.
      // However if the higher die has no legal move, it would have been returned already. But max=1 and both dice playable individually, only higher.
      return moves.filter(m => m.die === higher);
   }
   return moves;
}
```
