        rec(nb, rem.filter((_,j)=>j!==i), [...seq,m]);
      }
    }
    // if no move made, store current board as partial sequence (length less than full)
    if(tried.size===0 || results.length===? ) // problem: store terminal if no moves possible for any die
  }
}
```
