export function maxPlies(b,player,dice){
  if (dice.length===0) return 0;
  let best=0;
  const seen = new Set<number>();
  for (let i=0;i<dice.length;i++){
    const d=dice[i];
    if (seen.has(d)) continue; seen.add(d);
