```
export function allSequences(b,player,dice){
  const out:{board:Board;moves:Move[]}[]=[];
  function rec(cur:Board, rem:number[], seq:Move[]){
    if (rem.length===0){ out.push({board:cloneBoard(cur),moves:[...seq]}); return; }
    let progress=false;
    const seen=new Set<number>();
    for (let i=0;i<rem.length;i++){
      const d=rem[i];
      if (seen.has(d)) continue; seen.add(d);
      const ms=singleMoves(cur,player,d);
      if (ms.length>0) progress=true;
      for (const m of ms){
        const nb=cloneBoard(cur);
        applyMove(nb,player,m);
        rec(nb, rem.filter((_,j)=>j!==i), [...seq,m]);
      }
    }
    if (!progress) out.push({board:cloneBoard(cur),moves:[...seq]});
  }
  rec(b,dice,[]);
  return out;
}
```
