import type {...} ...

export type AiMoveResult = ...
export type CubeDecision = ...

const WIN_PROB_SCALE = 30;

export function evaluate(b,player): number {
  const opp = opponent(player);
  const selfPip = pipCount(b,player);
  const oppPip = pipCount(b,opp);
  let score = (oppPip - selfPip) * 2;
  score += (b.off[player] - b.off[opp]) * 25;
  score += (b.bar[opp] - b.bar[player]) * 15;
  // home board strength
  if (player==='white'){
    for (let i=1;i<=6;i++) { const n=b.points[i]; if (n>0) score += n*2; if (n===-1) score += 4; if (n<=-2) score -= n*2; }
    for (let i=19;i<=24;i++) { const n=b.points[i]; if (n<0) score -= (-n)*2; if (n===1) score -= 4; if (n>=2) score += n*2; }
  } else {
    for (let i=19;i<=24;i++) { const n=b.points[i]; if (n<0) score += (-n)*2; if (n===1) score += 4; if (n>=2) score -= n*2; }
    for (let i=1;i<=6;i++) { const n=b.points[i]; if (n>0) score -= n*2; if (n===-1) score -= 4; if (n<=-2) score += n*2; }
  }
  // blot penalty
  const sign = player==='white'?1:-1;
  for (let p=1;p<=24;p++){
    const n = b.points[p];
    if (n*sign===1) score -= 3; // own blot
    if (n*sign===-1) score += 3; // opp blot
  }
  return score;
}
```

