export function chooseMoves(b,player,dice,difficulty): AiMoveResult {
  const seqs = allSequences(b,player,dice);
  if (seqs.length===0) return {moves:[], board:cloneBoard(b)};
  const max = Math.max(...seqs.map(s=>s.moves.length));
  const legal = seqs.filter(s=>s.moves.length===max);
  if (difficulty==='easy'){
    const pick = legal[Math.floor(Math.random()*legal.length)];
    return {moves:pick.moves, board:cloneBoard(pick.board)};
  }
  let bestIndex = 0;
  let bestScore = -Infinity;
  legal.forEach((s,i)=>{
    const sc = evaluate(s.board,player);
    if (sc>bestScore){ bestScore=sc; bestIndex=i; }
  });
  if (difficulty==='medium' && Math.random()<0.2){
    const pick = legal[Math.floor(Math.random()*legal.length)];
    return {moves:pick.moves, board:cloneBoard(pick.board)};
  }
  return {moves:legal[bestIndex].moves, board:cloneBoard(legal[bestIndex].board)};
}
```
