export function shouldAiDouble(b,player,cube,difficulty){
  if (difficulty==='easy') return {action:'no-double', reasoning:'Easy AI does not double.'};
  if ((cube.owner && cube.owner !== player)) return {action:'no-double', reasoning:'Do not own cube.'};
  const prob=winProbability(b,player);
  const lower = difficulty==='hard'?0.68:0.72;
  if (prob>=lower && prob<=0.90) return {action:'double', reasoning:`Win probability ${(prob*100).toFixed(0)}% is in doubling window.`};
  return {action:'no-double', reasoning:`Win probability ${(prob*100).toFixed(0)}% outside window.`};
}

export function shouldAiAccept(b,player,difficulty){
  const prob=winProbability(b,player);
  const take = difficulty==='easy'?0.32: difficulty==='medium'?0.27:0.24;
  if (prob>=take) return {action:'double', reasoning:`Win probability ${(prob*100).toFixed(0)}% above take point.`};
  return {action:'no-double', reasoning:`Win probability ${(prob*100).toFixed(0)}% below take point.`};
}
```

