function finishGame(g: FullState, winner: Player, type: "single" | "gammon" | "backgammon" | null, declined: boolean = false) {
  if (g.counted) return;
  const mult = type ? multiplier(type) : 1;
  const pts = declined ? g.cube.value : (mult * g.cube.value);
  g.score[winner] += pts;
  g.pointsWon = pts;
  g.winner = winner;
  g.winType = type || "single";
  g.phase = "gameover";
  g.turnOver = true;
  g.gamesPlayed++;
  g.counted = true;
  const winnerName = winner === HUMAN ? "You" : "AI";
  g.message = `${winnerName} win${winner === HUMAN ? "" : "s"}! ${capitalize(g.winType)} (+${pts} points)`;
}
