function actionAi() {
  if (game.turn !== AI || game.phase === "gameover") return {};
  if (game.phase === "roll" && !game.aiCubeDone) {
    if ((game.cube.owner === null || game.cube.owner === AI) && shouldAiDouble(game,AI,game.cube,game.difficulty).action === "double") {
      game.phase = "doubleOffered";
      game.doubleOfferedBy = AI;
      game.aiCubeDone = true;
      game.message = "AI offers a double.";
      return { aiDouble: true };
    }
    game.aiCubeDone = true;
    return { aiNoDouble: true };
  }
  if (game.phase === "roll" && game.aiCubeDone) {
    const dice = rollDice(game);
    game.dice = dice;
    game.remainingDice = [...dice];
    game.phase = "move";
    const result = chooseMoves(game, AI, dice, game.difficulty);
    const moves = result.moves;
    for (const m of moves) {
      const hit = applyMove(game, AI, m);
      game.history.push({ ...m, hit });
      const di = game.remainingDice.indexOf(m.die);
      if (di >= 0) game.remainingDice.splice(di,1);
    }
    // handle messages / pass
    if (moves.length === 0) {
      game.message = "AI has no legal move and passes.";
    } else {
      game.message = `AI moved ${moves.length} checker${moves.length>1?'s':''}.`;
    }
    const win = checkWin(game, AI);
    if (win.won) {
      finishGame(game, AI, win.type as any);
    } else {
      // end AI turn, hand to human
      game.turn = HUMAN;
      game.phase = "roll";
      game.dice = [];
      game.remainingDice = [];
      game.turnOver = false;
      game.message = "Your turn. Roll the dice.";
    }
    return { aiMoves: moves };
  }
  return {};
}
```

