// Backgammon AI: move selection (easy/medium/hard) + doubling-cube reasoning.
import {
  type Board,
  type Move,
  type Player,
  allSequences,
  cloneBoard,
  pipCount,
  opponent,
} from "./game.ts";

export type AiMoveResult = { moves: Move[]; board: Board };
export type CubeDecision = { action: "double" | "no-double"; reasoning: string };

/** A scalar quality score of board `b` from `player`'s perspective (higher = better). */
export function evaluate(b: Board, player: Player): number {
  const opp = opponent(player);
  const selfPip = pipCount(b, player);
  const oppPip = pipCount(b, opp);

  // Pip race lead is the dominant signal.
  let score = (oppPip - selfPip) * 2;

  // Reward having borne off checkers and sent opponent checkers to the bar.
  score += (b.off[player] - b.off[opp]) * 25;
  score += (b.bar[opp] - b.bar[player]) * 15;

  // Home-board strength and blot pressure.
  const sign = player === "white" ? 1 : -1;
  if (player === "white") {
    for (let p = 1; p <= 6; p++) {
      const n = b.points[p];
      if (n > 0) score += n * 1.5;
      if (n < -1) score += (-n) * 1.5; // black points are blocked/home pressure
    }
    for (let p = 19; p <= 24; p++) {
      const n = b.points[p];
      if (n < 0) score -= (-n) * 1.0;
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      const n = b.points[p];
      if (n < 0) score += (-n) * 1.5;
      if (n > 1) score += n * 1.5;
    }
    for (let p = 1; p <= 6; p++) {
      const n = b.points[p];
      if (n > 0) score -= n * 1.0;
    }
  }

  // Blot penalties/rewards.
  for (let p = 1; p <= 24; p++) {
    const n = b.points[p];
    if (n * sign === 1) score -= 3; // own blot
    if (n * sign === -1) score += 3; // opponent blot
  }

  return score;
}

function randomChoice<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

/** Choose the AI's full-turn move sequence for the given `dice` at `difficulty`. */
export function chooseMoves(
  b: Board,
  player: Player,
  dice: number[],
  difficulty: "easy" | "medium" | "hard",
): AiMoveResult {
  const seqs = allSequences(b, player, dice);
  if (seqs.length === 0) {
    return { moves: [], board: cloneBoard(b) };
  }

  const maxLen = Math.max(...seqs.map((s) => s.moves.length));
  const legal = seqs.filter((s) => s.moves.length === maxLen);

  if (difficulty === "easy") {
    const pick = randomChoice(legal);
    return { moves: pick.moves, board: cloneBoard(pick.board) };
  }

  const scored = legal.map((s) => ({
    seq: s,
    value: evaluate(s.board, player),
  }));
  scored.sort((a, b) => b.value - a.value);

  if (difficulty === "medium" && Math.random() < 0.25) {
    const top = scored.slice(0, Math.min(3, scored.length)).map((s) => s.seq);
    const pick = randomChoice(top);
    return { moves: pick.moves, board: cloneBoard(pick.board) };
  }

  const best = scored[0].seq;
  return { moves: best.moves, board: cloneBoard(best.board) };
}

/** Estimate `player`'s probability of winning from board `b`, in [0,1]. */
export function winProbability(b: Board, player: Player): number {
  const diff = pipCount(b, opponent(player)) - pipCount(b, player);
  const p = 1 / (1 + Math.exp(-diff / 30));
  return Math.max(0, Math.min(1, p));
}

/** Decide whether the AI (`player`) should OFFER a double. */
export function shouldAiDouble(
  b: Board,
  player: Player,
  cube: { value: number; owner: Player | null },
  difficulty: "easy" | "medium" | "hard",
): CubeDecision {
  if (difficulty === "easy") {
    return { action: "no-double", reasoning: "Easy AI never offers a double." };
  }
  // Only offer when the AI may double (cube centered or owned by AI).
  if (cube.owner && cube.owner !== player) {
    return { action: "no-double", reasoning: "Opponent owns the cube; cannot double." };
  }
  const prob = winProbability(b, player);
  const lower = difficulty === "hard" ? 0.68 : 0.72;
  if (prob >= lower && prob <= 0.9) {
    return {
      action: "double",
      reasoning: `Win probability ${(prob * 100).toFixed(0)}% is inside the doubling window.`,
    };
  }
  return {
    action: "no-double",
    reasoning: `Win probability ${(prob * 100).toFixed(0)}% is outside the doubling window.`,
  };
}

/** Decide whether the AI (`player`) should ACCEPT a double the human just offered. */
export function shouldAiAccept(
  b: Board,
  player: Player,
  difficulty: "easy" | "medium" | "hard",
): CubeDecision {
  const prob = winProbability(b, player);
  const take = difficulty === "easy" ? 0.32 : difficulty === "medium" ? 0.27 : 0.24;
  if (prob >= take) {
    return { action: "double", reasoning: `Win probability ${(prob * 100).toFixed(0)}% is above the take point.` };
  }
  return { action: "no-double", reasoning: `Win probability ${(prob * 100).toFixed(0)}% is below the take point.` };
}

// Backgammon AI: move selection (easy/medium/hard) + doubling-cube reasoning.
import {
  type Board,
  type Move,
  type Player,
  allSequences,
  cloneBoard,
  pipCount,
  opponent,
} from "./game.ts";

export type AiMoveResult = { moves: Move[]; board: Board };
export type CubeDecision = { action: "double" | "no-double"; reasoning: string };

/** A scalar quality score of board `b` from `player`'s perspective (higher = better). */
export function evaluate(b: Board, player: Player): number {
  const opp = opponent(player);
  const selfPip = pipCount(b, player);
  const oppPip = pipCount(b, opp);

  // Pip race lead is the dominant signal.
  let score = (oppPip - selfPip) * 2;

  // Reward having borne off checkers and sent opponent checkers to the bar.
  score += (b.off[player] - b.off[opp]) * 25;
  score += (b.bar[opp] - b.bar[player]) * 15;

  // Home-board strength and blot pressure.
  if (player === "white") {
    for (let p = 1; p <= 6; p++) {
      const n = b.points[p];
      if (n > 0) score += n * 1.5;
      if (n < -1) score += (-n) * 1.5; // black points are blocked/home pressure
    }
    for (let p = 19; p <= 24; p++) {
      const n = b.points[p];
      if (n < 0) score -= (-n) * 1.0;
    }
  } else {
    for (let p = 19; p <= 24; p++) {
      const n = b.points[p];
      if (n < 0) score += (-n) * 1.5;
      if (n > 1) score += n * 1.5;
    }
    for (let p = 1; p <= 6; p++) {
      const n = b.points[p];
      if (n > 0) score -= n * 1.0;
    }
  }

  // Blot penalties/rewards.
  const sign = player === "white" ? 1 : -1;
  for (let p = 1; p <= 24; p++) {
    const n = b.points[p];
    if (n * sign === 1) score -= 3; // own blot
    if (n * sign === -1) score += 3; // opponent blot
  }

  return score;
}

function randomChoice<T>(arr: T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

/** Choose the AI's full-turn move sequence for the given `dice` at `difficulty`. */
export function chooseMoves(
  b: Board,
  player: Player,
  dice: number[],
  difficulty: "easy" | "medium" | "hard",
): AiMoveResult {
  const seqs = allSequences(b, player, dice);
  if (seqs.length === 0) {
    return { moves: [], board: cloneBoard(b) };
  }

  const maxLen = Math.max(...seqs.map((s) => s.moves.length));
  const legal = seqs.filter((s) => s.moves.length === maxLen);

  if (difficulty === "easy") {
    const pick = randomChoice(legal);
    return { moves: pick.moves, board: cloneBoard(pick.board) };
  }

  const scored = legal.map((s) => ({
    seq: s,
    value: evaluate(s.board, player),
  }));
  scored.sort((a, b) => b.value - a.value);

  if (difficulty === "medium" && Math.random() < 0.25) {
    const top = scored.slice(0, Math.min(3, scored.length)).map((s) => s.seq);
    const pick = randomChoice(top);
    return { moves: pick.moves, board: cloneBoard(pick.board) };
  }

  const best = scored[0].seq;
  return { moves: best.moves, board: cloneBoard(best.board) };
}

/** Estimate `player`'s probability of winning from board `b`, in [0,1]. */
export function winProbability(b: Board, player: Player): number {
