// Backgammon HTTP server — Node standard library only, serves API + static UI on :8002.
import http from "node:http";
import { readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

import { type GameState, type Move, type AppliedMove, type Player, type Board, BAR, OFF } from "./game.ts";
import {
  createGame,
  cloneBoard,
  legalMovesNow,
  applyMove,
  pipCount,
  checkWin,
  opponent,
} from "./game.ts";
import { chooseMoves, shouldAiDouble, shouldAiAccept } from "./ai.ts";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PUBLIC_DIR = path.join(__dirname, "..", "public");
const PORT = 8002;
const BENCH_DEBUG = process.env.BENCH_DEBUG === "1";
const HUMAN: Player = "white";
const AI: Player = "black";

interface FullState extends GameState {
  aiCubeDone: boolean;
  debugDiceQueue: number[][];
  counted: boolean;
}

let game: FullState = {} as FullState;

function init(difficulty: GameState["difficulty"] = "medium"): FullState {
  return {
    ...createGame(difficulty),
    aiCubeDone: false,
    debugDiceQueue: [],
    counted: false,
  };
}

function boardView(g: GameState): Board {
  return { points: g.points, bar: g.bar, off: g.off };
}

function multiplier(type: "single" | "gammon" | "backgammon" | null): number {
  if (type === "gammon") return 2;
  if (type === "backgammon") return 3;
  return 1;
}

function humanCanDouble(g: FullState): boolean {
  if (g.winner) return false;
  if (g.turn !== HUMAN) return false;
  if (g.phase !== "roll") return false;
  if (g.doubleOfferedBy) return false;
  if (g.cube.owner === AI) return false;
  return true;
}

function serialize(g: FullState, extra: Record<string, unknown> = {}): Record<string, unknown> {
  const legal =
    g.turn === HUMAN && g.phase === "move" && g.winner == null
      ? legalMovesNow(g, HUMAN, g.remainingDice)
      : [];
  return {
    points: g.points,
    bar: g.bar,
    off: g.off,
    turn: g.turn,
    phase: g.phase,
    dice: g.dice,
    remainingDice: g.remainingDice,
    cube: g.cube,
    difficulty: g.difficulty,
    score: g.score,
    winner: g.winner,
    winType: g.winType,
    pointsWon: g.pointsWon,
    doubleOfferedBy: g.doubleOfferedBy,
    message: g.message,
    turnOver: g.turnOver,
    gamesPlayed: g.gamesPlayed,
    pip: { white: pipCount(g, "white"), black: pipCount(g, "black") },
    legalMoves: legal,
    canDouble: humanCanDouble(g),
    ...extra,
  };
}

function finishGame(
  g: FullState,
  winner: Player,
  type: "single" | "gammon" | "backgammon" | null,
  declined = false,
) {
  if (g.counted) return;
  const mult = type ? multiplier(type) : 1;
  const pts = declined ? g.cube.value : mult * g.cube.value;
  g.score[winner] += pts;
  g.pointsWon = pts;
  g.winner = winner;
  g.winType = type || "single";
  g.phase = "gameover";
  g.turnOver = true;
  g.gamesPlayed += 1;
  g.counted = true;
  const name = winner === HUMAN ? "You win" : "AI wins";
  g.message = `${name}! ${capitalize(g.winType)} (+${pts} points)`;
}

function capitalize(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function refreshHumanTurn(g: FullState) {
  if (g.winner) return;
  if (g.turn !== HUMAN || g.phase !== "move") {
    g.turnOver = false;
    return;
  }
  if (g.remainingDice.length === 0) {
    g.turnOver = true;
    g.message = "All dice used. End your turn.";
    return;
  }
  const legal = legalMovesNow(g, HUMAN, g.remainingDice);
  if (legal.length === 0) {
    g.turnOver = true;
    g.message = "No legal move. Your turn passes automatically.";
  } else {
    g.turnOver = false;
    g.message = `Move using ${g.remainingDice.join(", ")}.`;
  }
}

function handOverToAi(g: FullState) {
  g.turn = AI;
  g.phase = "roll";
  g.dice = [];
  g.remainingDice = [];
  g.aiCubeDone = false;
  g.turnOver = false;
  g.message = "AI's turn.";
}

function handOverToHuman(g: FullState) {
  g.turn = HUMAN;
  g.phase = "roll";
  g.dice = [];
  g.remainingDice = [];
  g.turnOver = false;
  g.message = "Your turn. Roll the dice.";
}

function reverseMove(b: Board, player: Player, am: AppliedMove) {
  const sign = player === "white" ? 1 : -1;
  const opp = opponent(player);
  const oppSign = -sign;

  if (am.from === BAR) {
    b.bar[player] += 1;
  } else {
    b.points[am.from] += sign;
  }

  if (am.to === OFF) {
    b.off[player] -= 1;
    return;
  }

  b.points[am.to] -= sign;
  if (am.hit) {
    b.bar[opp] -= 1;
    b.points[am.to] += oppSign;
  }
}

function rollDice(g: FullState): number[] {
  if (g.debugDiceQueue.length > 0) {
    const forced = g.debugDiceQueue.shift() as number[];
    if (forced.length === 2 && forced[0] === forced[1]) {
      return Array(4).fill(forced[0]);
    }
    return [...forced].sort((a, b) => a - b);
  }
  const d1 = Math.floor(Math.random() * 6) + 1;
  const d2 = Math.floor(Math.random() * 6) + 1;
  if (d1 === d2) return Array(4).fill(d1);
  if (d1 < d2) return [d1, d2];
  return [d2, d1];
}

// ---------------- action handlers ----------------

function actionNew(body: any) {
  const diff = body?.difficulty ?? game.difficulty;
  const savedScore = { white: game.score.white, black: game.score.black };
  const savedGames = game.gamesPlayed;
  game = init(diff);
  game.score = savedScore;
  game.gamesPlayed = savedGames;
  game.message = "New game — white to roll.";
}

function actionRoll() {
  if (game.phase !== "roll" || game.turn !== HUMAN) {
    throw new Error("Cannot roll now.");
  }
  const dice = rollDice(game);
  game.dice = dice;
  game.remainingDice = [...dice];
  game.phase = "move";
  refreshHumanTurn(game);
}

function actionMove(body: any) {
  if (game.turn !== HUMAN || game.phase !== "move") {
    throw new Error("Not your move phase.");
  }
  const from = Number(body.from);
  const to = Number(body.to);
  const die = Number(body.die);
  const legal = legalMovesNow(game, HUMAN, game.remainingDice);
  const match = legal.find((m) => m.from === from && m.to === to && m.die === die);
  if (!match) throw new Error("Illegal move.");

  const hit = applyMove(game, HUMAN, match);
  game.history.push({ ...match, hit });
  const idx = game.remainingDice.indexOf(die);
  if (idx >= 0) game.remainingDice.splice(idx, 1);

  const win = checkWin(game, HUMAN);
  if (win.won) {
    finishGame(game, HUMAN, win.type);
  } else {
    refreshHumanTurn(game);
  }
}

function actionUndo() {
  if (game.turn !== HUMAN || game.phase !== "move" || game.history.length === 0) {
    throw new Error("Nothing to undo.");
  }
  const am = game.history.pop() as AppliedMove;
  reverseMove(game, HUMAN, am);
  game.remainingDice.push(am.die);
  game.remainingDice.sort((a, b) => a - b);
  refreshHumanTurn(game);
}

function actionEndTurn() {
  if (game.turn !== HUMAN || game.phase !== "move" || !game.turnOver) {
    throw new Error("Cannot end turn now.");
  }
  if (game.winner) return;
  handOverToAi(game);
}

function actionDouble() {
  if (!humanCanDouble(game)) throw new Error("Cannot double now.");
  game.phase = "doubleOffered";
  game.doubleOfferedBy = HUMAN;
  const decision = shouldAiAccept(game, AI, game.difficulty);
  if (decision.action === "double") {
    game.cube.value *= 2;
    game.cube.owner = AI;
    game.doubleOfferedBy = null;
    game.phase = "roll";
    game.message = `AI takes the double. Cube is now ${game.cube.value}.`;
    return { cubeAccepted: true };
  } else {
    finishGame(game, HUMAN, "single", true);
    return { cubeDeclined: true };
  }
}

function actionRespondDouble(body: any) {
  if (game.phase !== "doubleOffered" || game.doubleOfferedBy !== AI) {
    throw new Error("No AI double to respond to.");
  }
  const accept = body?.accept === true;
  if (accept) {
    game.cube.value *= 2;
    game.cube.owner = HUMAN;
    game.doubleOfferedBy = null;
    game.phase = "roll";
    game.message = "You take the double. AI to roll.";
  } else {
    finishGame(game, AI, "single", true);
  }
  return {};
}

function actionAi() {
  if (game.turn !== AI || game.phase === "gameover") {
    throw new Error("Not AI turn.");
  }
  if (game.phase === "doubleOffered") {
    throw new Error("AI is waiting for a cube response.");
  }

  if (game.phase === "roll" && !game.aiCubeDone) {
    const mayDouble = game.cube.owner === null || game.cube.owner === AI;
    if (
      mayDouble &&
      shouldAiDouble(game, AI, game.cube, game.difficulty).action === "double"
    ) {
      game.phase = "doubleOffered";
      game.doubleOfferedBy = AI;
      game.aiCubeDone = true;
      game.message = "AI offers a double.";
      return { aiDouble: true };
    }
    game.aiCubeDone = true;
    return { aiNoDouble: true };
  }

  if (game.phase === "roll" && game.aiCubeDone) {
    const dice = rollDice(game);
    game.dice = dice;
    game.remainingDice = [...dice];
    game.phase = "move";

    const result = chooseMoves(game, AI, dice, game.difficulty);
    for (const m of result.moves) {
      const hit = applyMove(game, AI, m);
      game.history.push({ ...m, hit });
      const di = game.remainingDice.indexOf(m.die);
      if (di >= 0) game.remainingDice.splice(di, 1);
    }

    if (result.moves.length === 0) {
      game.message = "AI has no legal move and passes.";
    } else {
      game.message = `AI moved ${result.moves.length} checker${result.moves.length > 1 ? "s" : ""}.`;
    }

    const win = checkWin(game, AI);
    if (win.won) {
      finishGame(game, AI, win.type);
    } else {
      handOverToHuman(game);
    }
    return { aiMoves: result.moves };
  }
  return {};
}

const DEBUG_ALLOWED_FIELDS = [
  "points",
  "bar",
  "off",
  "turn",
  "phase",
  "dice",
  "remainingDice",
  "cube",
  "difficulty",
  "score",
  "winner",
  "winType",
  "pointsWon",
  "doubleOfferedBy",
  "message",
];

function actionDebugState(body: any) {
  if (body && typeof body === "object") {
    for (const k of DEBUG_ALLOWED_FIELDS) {
      if (k in body) {
        (game as any)[k] = body[k];
      }
    }
    if (Array.isArray(game.points)) {
      while (game.points.length < 26) game.points.push(0);
      if (game.points.length > 26) game.points = game.points.slice(0, 26);
    }
    game.aiCubeDone = false;
    game.turnOver = body.turnOver ?? false;
    if (game.phase !== "gameover") {
      game.winner = body.winner ?? null;
    }
  }
  return {};
}

function actionDebugRoll(body: any) {
  if (!Array.isArray(body?.dice)) throw new Error("dice array required");
  game.debugDiceQueue.push([...body.dice].map(Number));
  return {};
}

// ---------------- HTTP plumbing ----------------

const MIME: Record<string, string> = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".json": "application/json; charset=utf-8",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
};

function readBody(req: http.IncomingMessage): Promise<any> {
  return new Promise((resolve) => {
    let data = "";
    req.on("data", (c) => (data += c));
    req.on("end", () => {
      if (!data) return resolve({});
      try {
        resolve(JSON.parse(data));
      } catch {
        resolve({});
      }
    });
  });
}

async function serveStatic(req: http.IncomingMessage, res: http.ServerResponse, urlPath: string) {
  let safePath = urlPath === "/" ? "/index.html" : urlPath;
  const filePath = path.join(PUBLIC_DIR, safePath);
  // Block directory traversal.
  if (!filePath.startsWith(path.resolve(PUBLIC_DIR))) {
    res.writeHead(403, { "Content-Type": "text/plain" }).end("Forbidden");
    return;
  }
  try {
    const data = await readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { "Content-Type": MIME[ext] || "application/octet-stream" });
    res.end(data);
  } catch (err: any) {
    if (err?.code === "ENOENT") {
      // SPA fallback.
      const html = await readFile(path.join(PUBLIC_DIR, "index.html"));
      res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
      res.end(html);
      return;
    }
    throw err;
  }
}

const server = http.createServer(async (req, res) => {
  const url = req.url || "/";
  try {
    if (req.method === "GET" && url.split("?")[0] === "/health") {
      const payload = JSON.stringify({ status: "ok", port: PORT });
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(payload);
      return;
    }

    if (url.startsWith("/api/")) {
      const body = req.method === "POST" ? await readBody(req) : {};
      let extra: Record<string, unknown> = {};
      switch (url.split("?")[0]) {
        case "/api/state":
          break;
        case "/api/new": {
          actionNew(body);
          break;
        }
        case "/api/roll":
          actionRoll();
          break;
        case "/api/move":
          actionMove(body);
          break;
        case "/api/undo":
          actionUndo();
          break;
        case "/api/endturn":
          actionEndTurn();
          break;
        case "/api/double":
          extra = actionDouble() || {};
          break;
        case "/api/double/respond":
          extra = actionRespondDouble(body) || {};
          break;
        case "/api/ai":
          extra = actionAi() || {};
          break;
        case "/api/debug/state":
          if (!BENCH_DEBUG) {
            res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
            return;
          }
          extra = actionDebugState(body) || {};
          break;
        case "/api/debug/roll":
          if (!BENCH_DEBUG) {
            res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
            return;
          }
          extra = actionDebugRoll(body) || {};
          break;
        default:
          res.writeHead(404, { "Content-Type": "application/json" }).end('{"error":"unknown endpoint"}');
          return;
      }
      const payload = JSON.stringify(serialize(game, extra));
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8" });
      res.end(payload);
      return;
    }
    await serveStatic(req, res, url);
  } catch (err) {
    console.error("Request error:", err);
    res.writeHead(500, { "Content-Type": "application/json" }).end(JSON.stringify({ error: String(err) }));
  }
});

server.on("error", (err: NodeJS.ErrnoException) => {
  if (err.code === "EADDRINUSE") {
    console.error(`Port ${PORT} is already in use.`);
    process.exit(1);
    return;
  }
  console.error(String(err));
  process.exit(1);
});

// Initialize the first game on boot.
game = init();

server.listen(PORT, () => {
  console.log(`Backgammon server running at http://localhost:${PORT}/`);
});

