input.content:
// Backgammon client UI.

const $ = (id) => document.getElementById(id);
const $$ = (sel) => Array.from(document.querySelectorAll(sel));

let state = null;
let selectedLoc = null;
let humanMoveCount = 0;
let lastDiceKey = "[]";
let aiTimer = null;
let diceAnimTimer = null;
let polling = null;

const HUMAN = "white";
const AI = "black";
const BAR_LOC = "bar";

const checkerEls = { white: [], black: [] };

async function api(path, body = {}) {
  const res = await fetch(path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  return res.json();
}

async function refresh() {
  state = await api("/api/state");
  render();
  maybeAi();
}

function render() {
  renderScores();
  renderCube();
  renderTurn();
  renderPips();
  renderDice();
  renderBoard();
  renderHints();
  renderControls();
  renderModal();
}

function renderScores() {
  $("scoreWhite").textContent = state.score.white;
  $("scoreBlack").textContent = state.score.black;
}

function renderCube() {
  $("cubeVal").textContent = String(state.cube.value);
  let owner = "centered";
  if (state.cube.owner === HUMAN) owner = "you";
  else if (state.cube.owner === AI) owner = "ai";
  $("cubeOwner").textContent = owner;
}

function renderTurn() {
  const el = $("turnIndicator");
  if (state.turn === HUMAN) {
    el.textContent = "You";
    el.className = "turnchip you";
  } else {
    el.textContent = "AI";
    el.className = "turnchip ai";
  }
}

function renderPips() {
  $("pipWhite").textContent = String(state.pip.white);
  $("pipBlack").textContent = String(state.pip.black);
}

// Dice dot map (indices in a 3x3 grid, top-left to bottom-right)
const PIP_MAP = {
  1: [4],
  2: [0, 8],
  3: [0, 4, 8],
  4: [0, 2, 6, 8],
  5: [0, 2, 4, 6, 8],
  6: [0, 2, 3, 5, 6, 8],
};

function renderDice() {
  const container = $("dice");
  container.innerHTML = "";
  if (!state.dice || state.dice.length === 0) return;

  const remainingCounts = {};
  state.remainingDice.forEach((d) => (remainingCounts[d] = (remainingCounts[d] || 0) + 1));
  const seenCounts = {};
  const rolling = JSON.stringify(state.dice) !== lastDiceKey;

  state.dice.forEach((d) => {
    seenCounts[d] = (seenCounts[d] || 0) + 1;
    const used = (remainingCounts[d] || 0) < seenCounts[d];
    const die = document.createElement("div");
    die.className = "die" + (used ? " used" : "") + (rolling ? " rolling" : "");
    die.dataset.testid = "die";
    for (let i = 0; i < 9; i++) {
      const dot = document.createElement("div");
      dot.className = "dot" + (PIP_MAP[d].includes(i) ? "" : " hidden");
      die.appendChild(dot);
    }
    container.appendChild(die);
  });

  lastDiceKey = JSON.stringify(state.dice);
  if (diceAnimTimer) clearTimeout(diceAnimTimer);
  if (rolling) {
    diceAnimTimer = setTimeout(() => {
      container.querySelectorAll(".die.rolling").forEach((d) => d.classList.remove("rolling"));
    }, 600);
  }
}

function ensureBoard() {
  const pf = $("playfield");
  if (pf.children.length > 0) return;

  const topLeft = [13, 14, 15, 16, 17, 18];
  const topRight = [19, 20, 21, 22, 23, 24];
  const bottomLeft = [12, 11, 10, 9, 8, 7];
  const bottomRight = [6, 5, 4, 3, 2, 1];

  function addPoint(p) {
    const div = document.createElement("div");
    div.className = "point " + (p >= 13 ? "top" : "bottom") + " " + (p % 2 === 0 ? "a" : "b");
    div.dataset.testid = "point";
    div.dataset.point = String(p);
    const lbl = document.createElement("div");
    lbl.className = "plabel";
    lbl.textContent = String(p);
    div.appendChild(lbl);
    pf.appendChild(div);
  }

  topLeft.forEach(addPoint);
  const bar = document.createElement("div");
  bar.className = "bar barcol";
  bar.dataset.testid = "bar";
  pf.appendChild(bar);
  topRight.forEach(addPoint);

  const offtray = document.createElement("div");
  offtray.className = "offtray";
  offtray.dataset.testid = "off-tray";
  const offAi = document.createElement("div");
  offAi.className = "offhalf top";
  offAi.dataset.testid = "off-ai";
  const offAiLbl = document.createElement("div");
  offAiLbl.className = "offlabel";
  offAiLbl.textContent = "AI";
  offAi.appendChild(offAiLbl);
  const offYou = document.createElement("div");
  offYou.className = "offhalf bottom";
  offYou.dataset.testid = "off-you";
  const offYouLbl = document.createElement("div");
  offYouLbl.className = "offlabel";
  offYouLbl.textContent = "You";
  offYou.appendChild(offYouLbl);
  offtray.appendChild(offAi);
  offtray.appendChild(offYou);
  pf.appendChild(offtray);

  bottomLeft.forEach(addPoint);
  bottomRight.forEach(addPoint);
}

function ensureCheckers() {
  const layer = $("checkerLayer");
  if (checkerEls.white.length > 0) return;
  ["white", "black"].forEach((color) => {
    for (let i = 0; i < 15; i++) {
      const el = document.createElement("div");
      el.className = "checker " + color;
      el.dataset.testid = "checker";
      el.dataset.color = color;
      el.style.display = "none";
      layer.appendChild(el);
      checkerEls[color].push(el);
    }
  });
}

function buildLocs(color) {
  const locs = [];
  for (let p = 1; p <= 24; p++) {
    const n = color === "white" ? state.points[p] : -state.points[p];
    for (let i = 0; i < n; i++) locs.push(String(p));
  }
  for (let i = 0; i < state.bar[color]; i++) locs.push(BAR_LOC);
  for (let i = 0; i < state.off[color]; i++) locs.push("off");
  return locs;
}

function getTargetEl(loc, color) {
  if (loc === BAR_LOC) return document.querySelector(".bar");
  if (loc === "off") {
    return document.querySelector(color === "white" ? ".offhalf.bottom" : ".offhalf.top");
  }
  return document.querySelector(`.point[data-point="${loc}"]`);
}

function checkerPosition(loc, color, idx, csize) {
  const el = getTargetEl(loc, color);
  const layerRect = $("checkerLayer").getBoundingClientRect();
  const rect = el.getBoundingClientRect();
  let x = rect.left + rect.width / 2 - csize / 2 - layerRect.left;
  let y;
  const step = csize * 0.88;
  if (loc === BAR_LOC || loc === "off") {
    if (color === AI) {
      y = rect.top + csize / 2 + idx * step - layerRect.top;
    } else {
      y = rect.bottom - csize / 2 - idx * step - layerRect.top;
    }
  } else {
    const p = Number(loc);
    const top = p >= 13;
    if (top) {
      y = rect.top + csize / 2 + idx * step - layerRect.top;
    } else {
      y = rect.bottom - csize / 2 - idx * step - layerRect.top;
    }
  }
  return { x, y };
}

function renderBoard() {
  ensureBoard();
  ensureCheckers();

  const csize = parseFloat(getComputedStyle(checkerEls.white[0]).width) || 32;
  const movableFrom = new Set();
  (state.legalMoves || []).forEach((m) => movableFrom.add(moveFromToLoc(m.from)));
  if (state.turn !== HUMAN || state.phase !== "move") movableFrom.clear();

  ["white", "black"].forEach((color) => {
    const locs = buildLocs(color);
    const locCounts = {};
    locs.forEach((loc) => (locCounts[loc] = (locCounts[loc] || 0) + 1));
    const seen = {};

    checkerEls[color].forEach((el, i) => {
      const loc = locs[i];
      if (!loc) {
        el.style.display = "none";
        delete el.dataset.loc;
        return;
      }
      el.dataset.loc = loc;
      seen[loc] = (seen[loc] || 0) + 1;
      const count = locCounts[loc];
      const limit = loc === BAR_LOC || loc === "off" ? Infinity : 5;
      const idx = seen[loc] - 1;
      if (idx >= limit) {
        el.style.display = "none";
        return;
      }
      el.style.display = "flex";

      const pos = checkerPosition(loc, color, idx, csize);
      el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;

      // Show count badge on the first visible checker of a stack.
      let badge = el.querySelector(".countbadge");
      if (!badge) {
        badge = document.createElement("span");
        badge.className = "countbadge";
        el.appendChild(badge);
      }
      badge.textContent = idx === 0 && count > 1 ? String(count) : "";

      // Selectable state.
      el.classList.remove("selectable", "selected");
      if (color === HUMAN && movableFrom.has(loc)) {
        el.classList.add("selectable");
        if (selectedLoc === loc) el.classList.add("selected");
      }
    });
  });
}

function moveFromToLoc(from) {
  return from === 0 ? BAR_LOC : String(from);
}

function moveToLoc(to) {
  return to === 25 ? "off" : String(to);
}

function renderHints() {
  const layer = $("pointHints");
  layer.innerHTML = "";
  if (!selectedLoc || !state.legalMoves) return;

  const csize = parseFloat(getComputedStyle(checkerEls.white[0]).width) || 32;
  const matches = state.legalMoves.filter((m) => moveFromToLoc(m.from) === selectedLoc);
  matches.forEach((m) => {
    const hint = document.createElement("div");
    hint.className = "hint";
    hint.dataset.testid = "hint";
    hint.textContent = m.to === 25 ? "off" : String(m.die);
    const dest = moveToLoc(m.to);
    // Position exactly where the checker would land, at the first stack slot.
    const color = HUMAN;
    const p = checkerPosition(dest, color, 0, csize);
    hint.style.transform = `translate(${p.x}px, ${p.y}px)`;
    hint.addEventListener("click", (e) => {
      e.stopPropagation();
      makeMove(m.from, m.to, m.die);
    });
    layer.appendChild(hint);
  });
}

function renderControls() {
  $("rollBtn").disabled = !(state.turn === HUMAN && state.phase === "roll" && !state.doubleOfferedBy);
  $("doubleBtn").disabled = !state.canDouble;
  $("undoBtn").disabled = !(state.turn === HUMAN && state.phase === "move" && humanMoveCount > 0);
  $("endTurnBtn").disabled = !(state.turn === HUMAN && state.phase === "move" && state.turnOver);
}

function renderModal() {
  const overlay = $("modalOverlay");
  const btns = $("modalBtns");
  btns.innerHTML = "";

  if (state.phase === "gameover" && state.winner) {
    overlay.classList.remove("hidden");
    const humanWin = state.winner === HUMAN;
    $("modalTitle").textContent = humanWin ? "Win" : "Game Over";
    $("modalBody").textContent = state.message || "";
    const btn = document.createElement("button");
    btn.className = "btn primary";
    btn.type = "button";
    btn.textContent = "New Game";
    btn.addEventListener("click", newGame);
    btns.appendChild(btn);
    return;
  }

  if (state.phase === "doubleOffered" && state.doubleOfferedBy === AI) {
    overlay.classList.remove("hidden");
    $("modalTitle").textContent = "Double Offered";
    $("modalBody").textContent = "The AI offers you a double.";
    const take = document.createElement("button");
    take.className = "btn primary";
    take.type = "button";
    take.textContent = "Take";
    take.addEventListener("click", () => respondDouble(true));
    const pass = document.createElement("button");
    pass.className = "btn";
    pass.type = "button";
    pass.textContent = "Pass";
    pass.addEventListener("click", () => respondDouble(false));
    btns.appendChild(take);
    btns.appendChild(pass);
    return;
  }

  overlay.classList.add("hidden");
}

async function makeMove(from, to, die) {
  try {
    await api("/api/move", { from, to, die });
    humanMoveCount += 1;
    selectedLoc = null;
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function roll() {
  try {
    await api("/api/roll");
    humanMoveCount = 0;
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function endTurn() {
  try {
    await api("/api/endturn");
    humanMoveCount = 0;
    selectedLoc = null;
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function undo() {
  try {
    await api("/api/undo");
    humanMoveCount = Math.max(0, humanMoveCount - 1);
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function offerDouble() {
  try {
    await api("/api/double");
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function respondDouble(accept) {
  try {
    await api("/api/double/respond", { accept });
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

async function newGame() {
  const diff = $("difficulty").value;
  try {
    await api("/api/new", { difficulty: diff });
    humanMoveCount = 0;
    selectedLoc = null;
    lastDiceKey = "[]";
    await refresh();
  } catch (err) {
    console.error(err);
  }
}

function maybeAi() {
  if (!state) return;
  if (state.turn === AI && state.phase !== "gameover" && !aiTimer) {
    aiTimer = setTimeout(async () => {
      aiTimer = null;
      try {
        await api("/api/ai");
        await refresh();
      } catch (err) {
        console.error(err);
      }
    }, 900);
  }
}

function setupEvents() {
  $("rollBtn").addEventListener("click", roll);
  $("endTurnBtn").addEventListener("click", endTurn);
  $("undoBtn").addEventListener("click", undo);
  $("doubleBtn").addEventListener("click", offerDouble);
  $("newGameBtn").addEventListener("click", newGame);

  $("checkerLayer").addEventListener("click", (e) => {
    const el = e.target.closest(".checker");
    if (!el) return;
    const loc = el.dataset.loc;
    if (!loc) return;
    if (selectedLoc === loc) {
      selectedLoc = null;
    } else {
      selectedLoc = loc;
    }
    renderHints();
    renderBoard();
  });

  document.addEventListener("click", (e) => {
    if (!e.target.closest(".checker") && !e.target.closest(".hint")) {
      selectedLoc = null;
      renderHints();
      renderBoard();
    }
  });
}

async function boot() {
  setupEvents();
  await refresh();
  polling = setInterval(refresh, 1500);
}

boot();

