let idxPerLoc = {};
checkerEls[color].forEach((el,i)=>{
  const loc = locs[i];
  if (!loc) { el.style.display='none'; return;}
  el.style.display='flex';
  el.dataset.loc = loc;
  const idx = idxPerLoc[loc] = (idxPerLoc[loc]||0)+1;
  const count = locCounts[loc];
  // determine visible index: if point and count>5, first 5 visible (idx 1..5), rest hidden.
  let visible = true;
  if (loc !== 'bar' && loc !== 'off' && count > 5 && idx > 5) visible=false;
  if (!visible) { el.style.display='none'; el.style.transform=''; return; }
  const offset = (loc!=='bar' && loc!=='off' && count>5)? idx-1 : idx-1; // 0-based stacking order
  const pos = checkerOffset(loc, color, offset, count, csize);
  el.style.transform = `translate(${pos.x}px, ${pos.y}px)`;
  // badge
  let badge = el.querySelector('.countbadge');
  if (!badge) { badge=document.createElement('span'); badge.className='countbadge'; el.appendChild(badge); }
  badge.textContent = count>1 ? String(count) : '';
});
